window.KMAP_EXTRA.usa = {"US-AK":[{"k":"symbol","zh":"畫著北斗七星與北極星的州旗，是1927年由14歲少年班尼·班森設計的。","en":"The state flag's Big Dipper and North Star were designed in 1927 by 14-year-old Benny Benson.","ja":"北斗七星と北極星を描いた州旗は、1927年に14歳の少年ベニー・ベンソンがデザインした。"},{"k":"sport","zh":"艾迪塔羅德狗拉雪橇賽每年3月舉行，全程約1,600公里。","en":"The Iditarod sled dog race runs each March across roughly 1,000 miles of wilderness.","ja":"犬ぞりレース「アイディタロッド」は毎年3月、約1600kmの荒野を走る。"},{"k":"work","zh":"迪士尼動畫《熊的傳說》的故事舞台，是冰河時期剛結束的○○。","en":"Disney's “Brother Bear” is set in ○○ just after the last ice age.","ja":"ディズニー映画『ブラザー・ベア』の舞台は、氷河期が終わったばかりの○○。"},{"k":"people","zh":"創作歌手珠兒（Jewel）在○○荷馬鎮附近的農場長大。","en":"Singer-songwriter Jewel grew up on a homestead near Homer, ○○.","ja":"シンガーソングライターのジュエルは、○○のホーマー近郊の農場で育った。"},{"k":"origin","zh":"州名來自阿留申語「alaxsxaq」，大意是「大陸本土」。","en":"The name comes from the Aleut word alaxsxaq, meaning roughly “the mainland.”","ja":"州名はアリュート語の「alaxsxaq」に由来し、おおよそ「本土」を意味する。"},{"k":"record","zh":"○○是美國最大的州，比德州、加州和蒙大拿加起來還大。","en":"○○ is the largest US state, bigger than Texas, California and Montana combined.","ja":"○○は米国最大の州で、テキサス・カリフォルニア・モンタナを合わせたより広い。"},{"k":"festival","zh":"安克拉治1935年開始的冬季「皮草交易節」，有馴鹿在市區街道上狂奔的活動。","en":"Anchorage's Fur Rendezvous winter festival, begun in 1935, features a “Running of the Reindeer” downtown.","ja":"1935年に始まったアンカレッジの冬祭り「ファー・ランデブー」では、トナカイが街なかを走る。"},{"k":"life","zh":"1925年白喉疫情時，雪橇犬隊接力把血清送到諾姆，領頭犬巴爾托因此成名。","en":"In 1925 sled dog teams relayed diphtheria serum to Nome, making the lead dog Balto famous.","ja":"1925年のジフテリア流行時、犬ぞりのリレーでノームへ血清が届けられ、先導犬バルトが有名になった。"}],
"US-AL":[{"k":"origin","zh":"州名來自當地一支原住民族的族名；常見的「我們在此休息」譯法其實沒有根據","en":"The name comes from a local Native American tribe; the popular translation 'here we rest' lacks scholarly support.","ja":"州名は先住民の部族名に由来する。よく聞く「ここで休む」という訳には根拠がない"},{"k":"people","zh":"又盲又聾的作家海倫·凱勒，1880年出生於○○的塔斯坎比亞","en":"Helen Keller, the deafblind author and activist, was born in Tuscumbia, ○○, in 1880.","ja":"目と耳が不自由だった作家ヘレン・ケラーは、1880年に○○のタスカンビアで生まれた"},{"k":"sport","zh":"○○大學與奧本大學的美式足球宿敵戰叫「鐵碗」，名稱來自伯明罕的鋼鐵業","en":"The Iron Bowl, the football rivalry between the University of ○○ and Auburn, is named for Birmingham's steel industry.","ja":"○○大学とオーバーン大学のフットボール宿命の対決「アイアンボウル」は、バーミングハムの鉄鋼業にちなむ"},{"k":"work","zh":"《梅岡城故事》作者哈波·李在○○的門羅維爾長大，梅岡城就是以家鄉為原型","en":"Harper Lee grew up in Monroeville, ○○, the inspiration for the town of Maycomb in To Kill a Mockingbird.","ja":"ハーパー・リーは○○のモンロービルで育ち、『To Kill a Mockingbird』の町メイコムは故郷がモデル"},{"k":"festival","zh":"多森號稱「世界花生之都」，每年11月舉辦全國花生節，最多吸引20萬人","en":"Dothan, the 'Peanut Capital of the World,' hosts the National Peanut Festival every November, drawing up to 200,000 people.","ja":"「世界のピーナッツの首都」ドーサンでは毎年11月に全米ピーナッツ祭りが開かれ、最大20万人が訪れる"},{"k":"symbol","zh":"州鳥是金翼啄木鳥，俗稱「黃鎚」；這外號原是給穿黃邊制服的騎兵隊的","en":"The state bird is the northern flicker, or 'yellowhammer,' a nickname first given to cavalry in yellow-trimmed uniforms.","ja":"州の鳥はハシボソキツツキ。愛称「イエローハンマー」は黄色い縁取りの軍服を着た騎兵隊に由来する"},{"k":"record","zh":"伯明罕的伏爾坎雕像高17公尺，是世界最大的鑄鐵雕像","en":"Birmingham's 17-meter Vulcan is the largest cast-iron statue in the world.","ja":"バーミングハムにある高さ17メートルのヴァルカン像は、世界最大の鋳鉄製の像だ"},{"k":"life","zh":"斯科茨伯勒有家店專賣航空公司無人認領的行李，是全美唯一的這種店","en":"Scottsboro's Unclaimed Baggage Center sells goods from lost airline luggage, the only store of its kind in the US.","ja":"スコッツボロには航空会社の引き取り手のない荷物を売る店があり、全米で唯一の存在だ"}],
"US-AR":[{"k":"origin","zh":"州名源自原住民語指稱夸帕族的詞，經法語拼寫而來，據信意為「南風之民」","en":"The name comes from a French spelling of an Algonquian word for the Quapaw people, believed to mean 'south wind people.'","ja":"州名は先住民クアポー族を指す言葉のフランス語表記に由来し、「南風の人々」の意味とされる"},{"k":"people","zh":"鄉村傳奇強尼·凱許1932年出生於○○的金斯蘭，在戴斯長大","en":"Country legend Johnny Cash was born in Kingsland, ○○, in 1932 and grew up in Dyess.","ja":"カントリーの伝説ジョニー・キャッシュは1932年に○○のキングスランドで生まれ、ダイエスで育った"},{"k":"sport","zh":"○○大學野豬隊的球迷會齊聲高喊「Woo Pig Sooie」呼喚豬隻","en":"Fans of the University of ○○ Razorbacks 'call the Hogs' by shouting 'Woo, Pig! Sooie!'","ja":"○○大学レイザーバックスのファンは「ウー、ピッグ、スーイー！」と叫んで豚を呼ぶ"},{"k":"work","zh":"瑪雅·安吉羅的自傳《我知道籠中鳥為何歌唱》大半發生在○○的小鎮斯坦普斯","en":"Much of Maya Angelou's memoir I Know Why the Caged Bird Sings takes place in Stamps, ○○.","ja":"マヤ・アンジェロウの自伝『歌え、翔べない鳥たちよ』の大半は、○○の町スタンプスが舞台"},{"k":"festival","zh":"「稻米與鴨子之都」斯圖加特每年感恩節那週舉辦世界鴨笛錦標賽","en":"Stuttgart, the 'Rice and Duck Capital of the World,' hosts the World Championship Duck Calling Contest every Thanksgiving week.","ja":"「米とカモの首都」スタットガートでは毎年感謝祭の週に、カモ笛の世界選手権が開かれる"},{"k":"symbol","zh":"州寶石是鑽石；州的官方水果和官方蔬菜，則是同一種粉紅番茄","en":"The state gem is the diamond, and the official state fruit and state vegetable are the same pink tomato.","ja":"州の宝石はダイヤモンド。州の果物と州の野菜は、同じピンクトマトだ"},{"k":"record","zh":"美國史上最大的鑽石「山姆大叔」重40.23克拉，1924年在○○出土","en":"The Uncle Sam, at 40.23 carats the largest diamond ever found in the US, was unearthed in ○○ in 1924.","ja":"米国で見つかった最大のダイヤ「アンクル・サム」（40.23カラット）は1924年に○○で掘り出された"},{"k":"life","zh":"負鼠派裡沒有負鼠，名字是說它把好幾層內餡藏在鮮奶油下「裝死」","en":"Possum pie contains no possum; it 'plays possum' by hiding its layers under whipped cream.","ja":"ポッサムパイにポッサムは入っていない。何層もの中身をホイップクリームの下に隠して「死んだふり」をするからだ"}],
"US-AZ":[{"k":"people","zh":"農工運動領袖凱薩·查維斯出生在尤馬。","en":"Farmworker leader Cesar Chavez was born in Yuma.","ja":"農業労働者運動の指導者セサール・チャベスはユマ生まれ。"},{"k":"people","zh":"奧斯卡影后艾瑪·史東出生在斯科茨代爾。","en":"Oscar winner Emma Stone was born in Scottsdale.","ja":"アカデミー賞女優エマ・ストーンはスコッツデール生まれ。"},{"k":"sport","zh":"每年春訓，15支大聯盟球隊集中在這裡打「仙人掌聯盟」熱身賽。","en":"Every spring, 15 MLB teams gather here for Cactus League spring training.","ja":"毎春、大リーグ15球団がここに集まり「カクタスリーグ」でキャンプを張る。"},{"k":"work","zh":"老鷹合唱團名曲《Take It Easy》唱到溫斯洛的街角，小鎮真的在那裡蓋了紀念公園。","en":"The Eagles' “Take It Easy” mentions a street corner in Winslow—and the town built a park on that corner.","ja":"イーグルスの名曲「テイク・イット・イージー」に歌われたウィンズロウの街角には、記念公園がある。"},{"k":"symbol","zh":"州花是巨人柱仙人掌的花，州鳥是仙人掌鷦鷯。","en":"The state flower is the saguaro blossom, and the state bird is the cactus wren.","ja":"州の花はサワロサボテンの花、州の鳥はサボテンミソサザイ。"},{"k":"origin","zh":"州名一般認為源自原住民奧哈姆語「小泉水」，經西班牙語轉寫而來。","en":"The name is thought to come, via Spanish, from an O'odham phrase meaning “small spring.”","ja":"州名はスペイン語を経て、オーダム語の「小さな泉」に由来するとされる。"},{"k":"record","zh":"紀錄上最高的巨人柱仙人掌高23.8公尺，1986年被暴風吹倒。","en":"The tallest saguaro on record, near Cave Creek, reached 78 ft (23.8 m) before a 1986 windstorm toppled it.","ja":"記録上最も高いサワロはケーブクリーク近くの23.8mで、1986年に暴風で倒れた。"},{"k":"life","zh":"因為全年不調時鐘，夏天和加州同一時間，冬天則和科羅拉多州同一時間。","en":"Because its clocks never change, it shares California's time in summer and Colorado's in winter.","ja":"時計を一年中変えないため、夏はカリフォルニア州、冬はコロラド州と同じ時刻になる。"}],
"US-CA":[{"k":"origin","zh":"州名取自約1510年西班牙小說裡，由女王卡拉菲亞統治的虛構島嶼。","en":"The name comes from a fictional island ruled by Queen Calafia in a Spanish novel from around 1510.","ja":"州名は1510年ごろのスペインの小説に登場する、女王カラフィアが治める架空の島の名に由来する。"},{"k":"people","zh":"蘋果創辦人賈伯斯1955年生於舊金山。","en":"Apple co-founder Steve Jobs was born in San Francisco in 1955.","ja":"アップル創業者スティーブ・ジョブズは1955年、サンフランシスコで生まれた。"},{"k":"people","zh":"瑪麗蓮·夢露1926年生於洛杉磯。","en":"Marilyn Monroe was born in Los Angeles in 1926.","ja":"マリリン・モンローは1926年、ロサンゼルスで生まれた。"},{"k":"work","zh":"電影《樂來越愛你》講述追夢的爵士鋼琴手和女演員在洛杉磯相戀。","en":"“La La Land” follows a jazz pianist and an aspiring actress falling in love in Los Angeles.","ja":"『ラ・ラ・ランド』は、ロサンゼルスで夢を追うジャズピアニストと女優の恋物語。"},{"k":"sport","zh":"大谷翔平效力的道奇隊，1958年才從紐約布魯克林搬到洛杉磯。","en":"The Dodgers, Shohei Ohtani's team, moved from Brooklyn, New York, to Los Angeles in 1958.","ja":"大谷翔平が所属するドジャースは、1958年にニューヨークのブルックリンからロサンゼルスへ移った。"},{"k":"festival","zh":"帕薩迪納的玫瑰花車遊行自1890年起在新年舉行，花車表面全用鮮花裝飾。","en":"Pasadena's Rose Parade has been held at New Year since 1890, with floats covered in real flowers.","ja":"パサデナのローズパレードは1890年から新年に開かれ、山車の表面は本物の花で覆われる。"},{"k":"symbol","zh":"○○的州化石是劍齒虎，洛杉磯的拉布雷亞瀝青坑挖出了上千隻。","en":"○○'s state fossil is the saber-toothed cat; thousands have been found in LA's La Brea Tar Pits.","ja":"○○の州の化石はサーベルタイガー。ロサンゼルスのラ・ブレア・タールピットから大量に出土した。"},{"k":"record","zh":"白山的刺果松「瑪土撒拉」樹齡超過4,800年，是已知最老的樹之一。","en":"Methuselah, a bristlecone pine in the White Mountains, is over 4,800 years old, among the oldest known trees.","ja":"ホワイト山地のブリッスルコーンパイン「メトシェラ」は樹齢4800年超で、知られる限り最古級の木。"}],
"US-CO":[{"k":"people","zh":"傳奇拳王傑克·登普西出生在曼納薩，綽號「曼納薩重錘」。","en":"Boxing legend Jack Dempsey was born in Manassa, earning the nickname “the Manassa Mauler.”","ja":"伝説のボクサー、ジャック・デンプシーはマナサ生まれで「マナサ・モーラー」と呼ばれた。"},{"k":"work","zh":"動畫《南方四賤客》的舞台是州內的虛構山城，創作者特雷·帕克就在這裡長大。","en":"“South Park” is set in a fictional mountain town here, and co-creator Trey Parker grew up in the state.","ja":"アニメ『サウスパーク』は州内の架空の山の町が舞台で、作者トレイ・パーカーもここで育った。"},{"k":"work","zh":"史蒂芬·金入住埃斯特斯公園的史丹利飯店後得到靈感，寫出了《鬼店》。","en":"A stay at the Stanley Hotel in Estes Park inspired Stephen King to write “The Shining.”","ja":"エステスパークのスタンレー・ホテルでの滞在が、スティーヴン・キングの『シャイニング』の着想になった。"},{"k":"sport","zh":"大聯盟洛磯隊主場空氣稀薄乾燥、球飛得遠，2002年起比賽用球都先放進恆濕室保存。","en":"Thin, dry air at the Rockies' Coors Field makes balls fly, so since 2002 game balls have been kept in a humidor.","ja":"ロッキーズの本拠地は空気が薄く乾燥して打球が飛ぶため、2002年から試合球を加湿室で保管する。"},{"k":"festival","zh":"「冷凍死人節」源自一位挪威老人的遺體被冷凍存放在小鎮倉庫，有棺材賽跑等活動。","en":"Frozen Dead Guy Days honors a Norwegian man's cryonically frozen body kept in a shed, with events like coffin races.","ja":"「冷凍死人祭り」は物置で冷凍保存されたノルウェー人の遺体にちなみ、棺桶レースなどを行う。"},{"k":"origin","zh":"州名是西班牙語「染成紅色的」，原本指帶著紅色泥沙的同名河流。","en":"The name is Spanish for “colored red,” first given to the reddish, silt-laden river of the same name.","ja":"州名はスペイン語で「赤く色づいた」の意味で、赤い泥を含む同名の川に由来する。"},{"k":"symbol","zh":"州鳥是百靈鵐，州花是藍白相間的耬斗菜。","en":"The state bird is the lark bunting, and the state flower is the white and lavender columbine.","ja":"州の鳥はカタジロクロシトド、州の花は白と薄紫のオダマキ。"},{"k":"life","zh":"洛磯隊主場上層看台第20排的座位漆成紫色，標示那裡正好海拔一英里。","en":"Row 20 of the upper deck at Coors Field is painted purple to mark exactly one mile above sea level.","ja":"ロッキーズ本拠地の上段席20列目は紫色で、ちょうど標高1マイルの位置を示す。"}],
"US-CT":[{"k":"people","zh":"馬戲大王巴納姆出生在○○的貝瑟爾，創辦了號稱「地表最盛大表演」的馬戲團。","en":"Circus showman P. T. Barnum was born in Bethel, ○○, and built what he billed as the Greatest Show on Earth.","ja":"サーカス王P・T・バーナムは○○のベセル生まれ。「地上最大のショウ」を築いた。"},{"k":"people","zh":"拿下 4 座奧斯卡影后、紀錄保持者凱瑟琳·赫本出生在○○。","en":"Katharine Hepburn, record holder with four Best Actress Oscars, was born in ○○.","ja":"アカデミー主演女優賞4回の最多記録を持つキャサリン・ヘプバーンは○○生まれ。"},{"k":"work","zh":"影集《奇異果女孩》的虛構小鎮星星谷，設定就在○○。","en":"Stars Hollow, the fictional town of Gilmore Girls, is set in ○○.","ja":"ドラマ『ギルモア・ガールズ』の架空の町スターズ・ホロウは○○にある設定。"},{"k":"sport","zh":"○○大學女籃拿過 12 次 NCAA 全國冠軍，是女籃史上最多。","en":"The state university's women's basketball team has won a record 12 NCAA national titles.","ja":"○○大学女子バスケ部はNCAA全米制覇12回で、女子史上最多。"},{"k":"origin","zh":"州名來自原住民語，意思是「長長的潮汐河」，指流經全州的大河。","en":"The name comes from a Native word meaning long tidal river, for the great river crossing the state.","ja":"州名は先住民の言葉で「長い潮の川」の意味。州を流れる大河を指す。"},{"k":"symbol","zh":"州的代表哺乳動物竟然是抹香鯨。","en":"The official state mammal is, surprisingly, the sperm whale.","ja":"州の哺乳類はなんとマッコウクジラ。"},{"k":"record","zh":"1776 年史上第一次潛艇攻擊，用的「海龜號」出自○○發明家布什內爾之手。","en":"The Turtle, used in history's first submarine attack in 1776, was invented by ○○'s David Bushnell.","ja":"1776年、史上初の潜水艇攻撃に使われた「タートル号」は○○のブッシュネルが発明。"},{"k":"life","zh":"連鎖潛艇堡 Subway 在 1965 年創立於○○的橋港。","en":"The sandwich chain Subway was founded in Bridgeport, ○○, in 1965.","ja":"サンドイッチチェーンのサブウェイは1965年、○○のブリッジポートで創業。"}],
"US-DE":[{"k":"people","zh":"拜登代表○○當了 36 年聯邦參議員，之後成為第 46 任總統。","en":"Joe Biden represented ○○ in the US Senate for 36 years before becoming the 46th president.","ja":"バイデンは○○選出の上院議員を36年務め、のちに第46代大統領になった。"},{"k":"festival","zh":"選後兩天，喬治城舉辦「歸來日」，勝選與落選者同車遊行，再把斧頭埋進沙裡。","en":"Two days after elections, Georgetown holds Return Day: winners and losers ride together, then bury a hatchet in sand.","ja":"選挙の2日後、ジョージタウンの「リターン・デー」では勝者と敗者が同じ馬車でパレードし、斧を砂に埋める。"},{"k":"work","zh":"電影《春風化雨》的故事設定在佛蒙特，其實主要在○○拍攝。","en":"Dead Poets Society is set in Vermont, but it was mostly filmed in ○○.","ja":"映画『いまを生きる』の舞台はバーモントだが、撮影は主に○○で行われた。"},{"k":"origin","zh":"州名來自一位英國男爵的封號，他是維吉尼亞殖民地的首任總督。","en":"The name comes from the title of an English baron who was the first governor of colonial Virginia.","ja":"州名は、ヴァージニア植民地の初代総督だったイギリスの男爵の称号に由来する。"},{"k":"record","zh":"1638 年瑞典人在這裡建立「新瑞典」殖民地，據說也把木屋建法帶進北美。","en":"Swedes founded New Sweden here in 1638 and are said to have brought the log cabin to North America.","ja":"1638年、スウェーデン人がここに「ニュースウェーデン」を築き、丸太小屋を北米に伝えたとされる。"},{"k":"sport","zh":"首府的賽車場以難跑出名，被暱稱為「怪獸一英里」。","en":"The NASCAR track in the state capital is so tough it is nicknamed the Monster Mile.","ja":"州都のサーキットは難コースで知られ、「モンスター・マイル」と呼ばれる。"},{"k":"symbol","zh":"州花是桃花，州樹是美國冬青。","en":"The state flower is the peach blossom, and the state tree is the American holly.","ja":"州花はモモの花、州木はアメリカヒイラギ。"},{"k":"life","zh":"海濱小鎮雷霍伯斯海灘自稱「國家的夏都」。","en":"The beach town of Rehoboth Beach calls itself The Nation's Summer Capital.","ja":"海辺の町リホボス・ビーチは「国の夏の首都」を名乗る。"}],
"US-FL":[{"k":"origin","zh":"1513年西班牙探險家龐塞·德萊昂命名，取自遍地花草或復活節的西班牙語說法","en":"Spanish explorer Ponce de León named it in 1513, after its abundant flowers or the Easter season.","ja":"1513年、スペインの探検家ポンセ・デ・レオンが、咲き誇る花または復活祭にちなんで名付けた"},{"k":"people","zh":"歌手亞莉安娜·格蘭德出生於○○的博卡拉頓","en":"Singer Ariana Grande was born in Boca Raton, ○○.","ja":"歌手アリアナ・グランデは○○のボカラトン生まれ"},{"k":"sport","zh":"代托納500號稱「美國大賽」，自1982年起一直是NASCAR賽季的開幕戰","en":"The Daytona 500, 'The Great American Race,' has opened the NASCAR Cup season every year since 1982.","ja":"「グレート・アメリカン・レース」デイトナ500は、1982年からNASCARカップの開幕戦だ"},{"k":"work","zh":"電影《疤面煞星》(1983)講古巴移民東尼·蒙大拿在邁阿密崛起的故事","en":"The film Scarface (1983) follows Cuban immigrant Tony Montana's rise in Miami.","ja":"映画『スカーフェイス』（1983年）は、キューバ移民トニー・モンタナがマイアミでのし上がる物語"},{"k":"festival","zh":"坦帕每年1月有加斯帕里拉海盜節，海盜船開進市區、向市長討城市鑰匙","en":"At Tampa's Gasparilla Pirate Festival each January, a pirate ship sails in and the crew demands the key to the city.","ja":"タンパの「ガスパリラ海賊祭り」では毎年1月、海賊船が乗り込み、市長に街の鍵を要求する"},{"k":"symbol","zh":"州飲料是柳橙汁，州的海洋哺乳動物是海牛","en":"The state beverage is orange juice, and the state marine mammal is the manatee.","ja":"州の飲み物はオレンジジュース、州の海洋哺乳類はマナティーだ"},{"k":"record","zh":"1969年人類首次登月的阿波羅11號，是從○○的甘迺迪太空中心升空的","en":"Apollo 11, the first crewed Moon landing mission, lifted off from Kennedy Space Center in ○○ in 1969.","ja":"1969年に人類初の月面着陸を果たしたアポロ11号は、○○のケネディ宇宙センターから打ち上げられた"},{"k":"life","zh":"基韋斯特的「美國本土最南端」浮標其實不在最南點，真正的最南端是一座私人小島","en":"Key West's 'Southernmost Point' buoy isn't truly the southernmost spot; that is Ballast Key, a private island.","ja":"キーウェストの「米本土最南端」のブイは実は最南端ではない。本当の最南端は私有の小島バラスト・キー"}],
"US-GA":[{"k":"people","zh":"民權領袖金恩博士1929年出生於○○的首府","en":"Civil rights leader Martin Luther King Jr. was born in ○○'s capital in 1929.","ja":"公民権運動の指導者キング牧師は1929年、○○の州都で生まれた"},{"k":"sport","zh":"高爾夫名人賽每年在奧古斯塔舉行，是四大賽中唯一固定在同一座球場的","en":"The Masters, held every year at Augusta National, is the only golf major always played at the same course.","ja":"ゴルフのマスターズは毎年オーガスタで開かれ、4大大会で唯一、同じコースで行われる"},{"k":"work","zh":"小說《飄》以南北戰爭時期的○○為舞台，作者米契爾1937年獲普立茲獎","en":"Gone with the Wind is set in ○○ during the Civil War; author Margaret Mitchell won the 1937 Pulitzer Prize.","ja":"小説『風と共に去りぬ』は南北戦争期の○○が舞台。作者ミッチェルは1937年にピュリッツァー賞を受賞"},{"k":"symbol","zh":"2002年州政府把玉米粥(grits)定為官方指定料理","en":"In 2002 the state declared grits its official prepared food.","ja":"2002年、州はトウモロコシのかゆ「グリッツ」を公式の料理に定めた"},{"k":"symbol","zh":"雷·查爾斯唱紅的〈○○ on My Mind〉1979年成為州歌，他就出生在州內的奧爾巴尼","en":"Ray Charles's version of '○○ on My Mind' became the state song in 1979; he was born in Albany, ○○.","ja":"レイ・チャールズの「○○・オン・マイ・マインド」は1979年に州歌となった。彼は州内のオールバニ生まれ"},{"k":"life","zh":"首府有71條街名裡帶著「Peachtree（桃樹）」","en":"The state capital has 71 streets with a variant of 'Peachtree' in their name.","ja":"州都には「ピーチツリー」の名が付く通りが71本もある"}],
"US-HI":[{"k":"people","zh":"第44任美國總統歐巴馬1961年出生於○○。","en":"Barack Obama, the 44th US president, was born in ○○ in 1961.","ja":"第44代米国大統領バラク・オバマは1961年に○○で生まれた。"},{"k":"people","zh":"「現代衝浪之父」杜克·卡哈納莫庫，也是奧運游泳金牌得主。","en":"Duke Kahanamoku, the father of modern surfing, also won Olympic gold medals in swimming.","ja":"「近代サーフィンの父」デューク・カハナモクは、五輪競泳の金メダリストでもある。"},{"k":"sport","zh":"鐵人三項賽1978年誕生於歐胡島，第一屆只有15人出發。","en":"The Ironman triathlon was born on Oahu in 1978; only 15 men started the first race.","ja":"アイアンマン・トライアスロンは1978年にオアフ島で誕生。第1回の出走者は15人だけだった。"},{"k":"work","zh":"迪士尼動畫《星際寶貝》的故事發生在考艾島。","en":"Disney's “Lilo & Stitch” is set on the island of Kauai.","ja":"ディズニー映画『リロ・アンド・スティッチ』の舞台はカウアイ島。"},{"k":"festival","zh":"希洛的「歡樂君王節」自1964年起舉辦，是頂尖的草裙舞大賽，名稱紀念國王卡拉卡瓦。","en":"Hilo's Merrie Monarch Festival, a top hula competition since 1964, honors King Kalākaua.","ja":"ヒロの「メリー・モナーク・フェスティバル」は1964年から続く最高峰のフラ大会で、カラカウア王にちなむ。"},{"k":"festival","zh":"每年5月1日是「花環節（Lei Day）」，自1928年起大家戴上花環慶祝。","en":"May 1 is Lei Day, celebrated with flower leis since 1928.","ja":"5月1日は「レイ・デー」。1928年から花のレイを身につけて祝われている。"},{"k":"symbol","zh":"州魚是斜帶吻棘魨，當地名字叫「humuhumunukunukuāpuaʻa」，長得驚人。","en":"The state fish, the reef triggerfish, has the famously long local name humuhumunukunukuāpuaʻa.","ja":"州の魚はムラサメモンガラ。現地語の名前は「フムフムヌクヌクアプアア」と驚くほど長い。"},{"k":"origin","zh":"州名一說來自傳說中發現群島的航海家，一說源自玻里尼西亞古語的「故鄉」。","en":"The name may honor a legendary navigator who found the islands, or come from an old Polynesian word for “homeland.”","ja":"州名は島を見つけた伝説の航海者の名、またはポリネシア古語の「故郷」に由来するとされる。"}],
"US-IA":[{"k":"people","zh":"西部片巨星約翰·韋恩出生於溫特塞特。","en":"Western film star John Wayne was born in Winterset.","ja":"西部劇の大スター、ジョン・ウェインはウィンターセット生まれ。"},{"k":"people","zh":"胡佛總統出生於西布蘭奇，是唯一在○○出生的美國總統。","en":"President Herbert Hoover was born in West Branch, the only US president born in ○○.","ja":"フーヴァー大統領はウェストブランチ生まれで、○○出身の唯一の大統領。"},{"k":"work","zh":"電影《夢幻成真》的玉米田棒球場在戴爾斯維爾，2021年大聯盟真的在旁邊打了正式比賽。","en":"The Field of Dreams cornfield diamond is in Dyersville; in 2021 MLB played a real game next to it.","ja":"映画『フィールド・オブ・ドリームス』の球場はダイアーズビルにあり、2021年にはMLBが隣で公式戦を行った。"},{"k":"work","zh":"電影《麥迪遜之橋》就在故事發生地麥迪遜郡實地拍攝。","en":"The Bridges of Madison County was filmed in Madison County itself, where the story takes place.","ja":"映画『マディソン郡の橋』は、物語の舞台マディソン郡で実際に撮影された。"},{"k":"festival","zh":"州博覽會從1911年起展出用奶油雕成的真實大小乳牛。","en":"Since 1911 the state fair has displayed a life-size cow sculpted from butter.","ja":"州のフェアでは1911年から、バターで作った実物大の牛が展示されている。"},{"k":"festival","zh":"每年七月的單車活動RAGBRAI，從西邊的密蘇里河騎到東邊的密西西比河，橫越全州。","en":"Each July the RAGBRAI bike ride crosses the whole state from the Missouri River to the Mississippi.","ja":"毎年7月の自転車イベントRAGBRAIは、西のミズーリ川から東のミシシッピ川まで州を横断する。"},{"k":"symbol","zh":"州石是晶洞石，外表像普通石頭，敲開裡面是一片水晶。","en":"The state rock is the geode, a plain-looking stone that reveals crystals when cracked open.","ja":"州の石はジオード。見た目は普通の石だが、割ると中に結晶が詰まっている。"},{"k":"sport","zh":"州內沒有四大職業聯盟球隊，兩所州內大學每年爭奪「Cy-Hawk獎盃」。","en":"With no major-league pro teams, fans focus on the two big state universities' yearly fight for the Cy-Hawk Trophy.","ja":"四大プロリーグのチームはなく、州内2大学が毎年「サイホーク・トロフィー」を争う。"}],
"US-ID":[{"k":"people","zh":"詩人艾茲拉·龐德1885年生於○○的小鎮海利。","en":"Poet Ezra Pound was born in 1885 in the small town of Hailey, ○○.","ja":"詩人エズラ・パウンドは1885年、○○の小さな町ヘイリーで生まれた。"},{"k":"people","zh":"海明威晚年住在○○的凱瓊，1961年在那裡過世，也長眠於此。","en":"Ernest Hemingway spent his last years in Ketchum, ○○, where he died in 1961 and is buried.","ja":"ヘミングウェイは晩年を○○のケッチャムで過ごし、1961年にそこで亡くなり、今もそこに眠る。"},{"k":"work","zh":"電影《Napoleon Dynamite》的故事發生在○○的小鎮普雷斯頓，也在當地拍攝。","en":"The film “Napoleon Dynamite” is set in the small town of Preston, ○○, and was shot there.","ja":"映画『ナポレオン・ダイナマイト』の舞台は○○の小さな町プレストンで、撮影も現地で行われた。"},{"k":"festival","zh":"全美老式小提琴大賽自1953年起，每年6月在○○的小鎮韋瑟舉行。","en":"The National Oldtime Fiddlers' Contest has been held each June in Weiser, ○○, since 1953.","ja":"全米オールドタイム・フィドル大会は1953年から毎年6月、○○の町ウィーザーで開かれている。"},{"k":"origin","zh":"州名據稱是原住民語「山上的寶石」，但很可能是19世紀有人捏造的。","en":"The name was said to mean “gem of the mountains” in a Native language, but it was likely made up in the 1800s.","ja":"州名は先住民の言葉で「山の宝石」の意味とされたが、19世紀の作り話だった可能性が高い。"},{"k":"symbol","zh":"○○的州馬是阿帕盧薩馬，是當地內茲珀斯族培育出的斑點馬。","en":"○○'s state horse is the Appaloosa, a spotted breed developed by the Nez Perce people.","ja":"○○の州の馬はアパルーサ。先住民ネズパース族が育てた斑点模様の馬だ。"},{"k":"record","zh":"肖松尼瀑布高約65公尺，比尼加拉瓜瀑布還高，人稱「西部的尼加拉」。","en":"Shoshone Falls is about 212 feet high, taller than Niagara Falls, and is called the “Niagara of the West.”","ja":"ショショーニ滝は高さ約65mでナイアガラの滝より高く、「西部のナイアガラ」と呼ばれる。"},{"k":"life","zh":"記憶體晶片大廠美光科技的總部就設在○○。","en":"Memory-chip giant Micron Technology is headquartered in ○○.","ja":"メモリ半導体大手マイクロン・テクノロジーの本社は○○にある。"}],
"US-IL":[{"k":"people","zh":"華特·迪士尼出生於芝加哥。","en":"Walt Disney was born in Chicago.","ja":"ウォルト・ディズニーはシカゴ生まれ。"},{"k":"people","zh":"文豪海明威出生於芝加哥近郊的橡樹園。","en":"Ernest Hemingway was born in Oak Park, just outside Chicago.","ja":"文豪ヘミングウェイはシカゴ近郊のオークパーク生まれ。"},{"k":"sport","zh":"芝加哥小熊隊2016年拿下世界大賽冠軍，終結了108年的冠軍荒。","en":"The Chicago Cubs won the 2016 World Series, ending a 108-year title drought.","ja":"シカゴ・カブスは2016年にワールドシリーズを制し、108年ぶりの優勝を果たした。"},{"k":"work","zh":"電影《翹課天才》講的是芝加哥郊區高中生翹課一天玩遍市區的故事。","en":"In the film Ferris Bueller's Day Off, a suburban teen skips school to roam Chicago for a day.","ja":"映画『フェリスはある朝突然に』は、郊外の高校生が学校をさぼってシカゴで遊び回る物語。"},{"k":"work","zh":"電影《小鬼當家》裡那棟房子位在芝加哥北郊的溫內特卡。","en":"The house in Home Alone is in Winnetka, a suburb north of Chicago.","ja":"映画『ホーム・アローン』の家は、シカゴ北郊のウィネトカにある。"},{"k":"festival","zh":"樂帕路莎音樂節從2005年起固定在芝加哥格蘭特公園舉辦。","en":"Since 2005, Lollapalooza has made Chicago's Grant Park its permanent home.","ja":"ロラパルーザは2005年からシカゴのグラント・パークを定位置として開かれている。"},{"k":"record","zh":"1885年在芝加哥完工的家庭保險大樓，被視為世界第一棟摩天大樓。","en":"Chicago's Home Insurance Building, completed in 1885, is considered the world's first skyscraper.","ja":"1885年にシカゴで完成したホーム・インシュアランス・ビルは、世界初の超高層ビルとされる。"},{"k":"origin","zh":"州名源自原住民語的一個動詞，意思大約是「說話方式很正常」。","en":"The name comes from a Native verb meaning roughly \"he speaks the regular way.\"","ja":"州名は先住民の言葉の動詞に由来し、「普通に話す」という意味だという。"}],
"US-IN":[{"k":"people","zh":"流行樂之王麥可·傑克森出生於鋼鐵城市蓋瑞。","en":"The King of Pop, Michael Jackson, was born in the steel city of Gary.","ja":"キング・オブ・ポップ、マイケル・ジャクソンは鉄鋼の町ゲーリー生まれ。"},{"k":"people","zh":"《養子不教誰之過》的影星詹姆斯·狄恩出生於○○的馬里恩。","en":"Rebel Without a Cause star James Dean was born in Marion, ○○.","ja":"『理由なき反抗』のジェームズ・ディーンは○○のマリオン生まれ。"},{"k":"sport","zh":"NFL小馬隊1984年趁深夜用搬家卡車從巴爾的摩搬到首府。","en":"In 1984 the NFL's Colts left Baltimore overnight in moving vans, relocating to the capital.","ja":"NFLのコルツは1984年、夜中に引っ越しトラックでボルチモアから州都へ移転した。"},{"k":"work","zh":"喜劇影集《公園與遊憩》的虛構小鎮波尼，也設定在○○。","en":"Pawnee, the fictional town in the sitcom Parks and Recreation, is also set in ○○.","ja":"コメディ『パークス・アンド・レクリエーション』の架空の町ポーニーも○○にある設定。"},{"k":"festival","zh":"小鎮米契爾每年九月舉辦柿子節，會場賣柿子布丁和柿子冰淇淋。","en":"Each September the town of Mitchell holds a Persimmon Festival, selling persimmon pudding and ice cream.","ja":"ミッチェルの町では毎年9月に柿祭りが開かれ、柿のプディングやアイスが売られる。"},{"k":"symbol","zh":"州花是牡丹。","en":"The state flower is the peony.","ja":"州の花はシャクヤク（ピオニー）。"},{"k":"record","zh":"首府的500英里賽車被稱為全世界單日現場觀眾最多的體育賽事。","en":"The capital's 500-mile race is called the world's largest single-day sporting event.","ja":"州都の500マイルレースは、1日の観客数で世界最大のスポーツイベントといわれる。"},{"k":"life","zh":"小鎮「聖誕老人」有志工組成的「聖誕老人的小精靈」，回覆世界各地孩子寄來的信。","en":"In the town of Santa Claus, volunteers called Santa's Elves answer letters sent by children worldwide.","ja":"サンタクロースという町では、「サンタの妖精」と呼ばれるボランティアが世界中の子どもの手紙に返事を書く。"}],
"US-KS":[{"k":"people","zh":"女飛行家愛蜜莉亞·艾爾哈特出生於艾奇森。","en":"Aviator Amelia Earhart was born in Atchison.","ja":"女性飛行家アメリア・イアハートはアチソン生まれ。"},{"k":"people","zh":"默片喜劇大師巴斯特·基頓出生於○○的小鎮皮夸。","en":"Silent-film comedy great Buster Keaton was born in the small town of Piqua, ○○.","ja":"サイレント喜劇の巨匠バスター・キートンは○○の小さな町ピクア生まれ。"},{"k":"sport","zh":"奈史密斯手寫的籃球原始規則2010年以約434萬美元拍出，捐給他執教過的大學。","en":"Naismith's original handwritten basketball rules sold for about $4.3 million in 2010 and were given to the university he coached.","ja":"ネイスミス直筆のバスケ原典ルールは2010年に約434万ドルで落札され、彼が指導した大学に寄贈された。"},{"k":"work","zh":"《綠野仙蹤》的女主角桃樂絲來自○○，被龍捲風吹到了奧茲國。","en":"Dorothy of The Wizard of Oz comes from ○○ and is swept to Oz by a tornado.","ja":"『オズの魔法使い』のドロシーは○○の出身で、竜巻でオズの国へ飛ばされる。"},{"k":"work","zh":"卡波提的紀實小說《冷血》，寫的是1959年霍爾科姆小鎮的一家滅門案。","en":"Truman Capote's nonfiction novel In Cold Blood recounts a 1959 family murder in the small town of Holcomb.","ja":"カポーティのノンフィクション小説『冷血』は、1959年にホルコムの町で起きた一家殺害事件を描く。"},{"k":"origin","zh":"州名源自當地原住民族名，常被說成「南風之民」的意思。","en":"The name comes from a local Native people and is often said to mean \"people of the south wind.\"","ja":"州名は先住民の部族名に由来し、「南風の民」という意味だとよくいわれる。"},{"k":"symbol","zh":"2022年起州果是野生的沙丘李。","en":"Since 2022 the state fruit has been the wild sandhill plum.","ja":"2022年から、州の果物は野生のサンドヒル・プラム。"},{"k":"life","zh":"小鎮盧卡斯有座「伊甸園」，是一名退伍軍人用水泥親手打造的雕塑庭園。","en":"The town of Lucas has the Garden of Eden, a concrete sculpture garden built by hand by a Civil War veteran.","ja":"ルーカスの町には、南北戦争の退役軍人がコンクリートで手作りした彫刻庭園「エデンの園」がある。"}],
"US-KY":[{"k":"origin","zh":"州名來自同名的河流，語源不明，一說出自原住民語的「在草原上」","en":"The state is named after a river; the origin is uncertain, possibly an Iroquoian term for 'on the meadow.'","ja":"州名は同名の川に由来する。語源ははっきりせず、先住民の言葉で「草原の上」とする説がある"},{"k":"people","zh":"拳王阿里1942年出生於○○的路易斯維爾","en":"Boxing great Muhammad Ali was born in Louisville, ○○, in 1942.","ja":"ボクシングの伝説モハメド・アリは1942年、○○のルイビルで生まれた"},{"k":"sport","zh":"○○德比自1875年起每年舉行，比賽只有約兩分鐘，冠軍馬會披上554朵玫瑰","en":"The ○○ Derby has run every year since 1875; the race lasts about two minutes and the winner gets a blanket of 554 roses.","ja":"○○ダービーは1875年から毎年開催。レースは約2分で、勝ち馬には554本のバラの掛け物が贈られる"},{"k":"work","zh":"影集《Justified》以○○東部的哈蘭郡為舞台","en":"The TV series Justified is set in Harlan County in eastern ○○.","ja":"ドラマ『JUSTIFIED 俺の正義』は○○東部のハーラン郡が舞台"},{"k":"festival","zh":"德比節以「路易斯維爾之雷」揭幕，它曾是北美規模最大的年度煙火秀","en":"Thunder Over Louisville kicks off the Derby Festival and was once North America's largest annual fireworks show.","ja":"ダービー祭りの幕開け「サンダー・オーバー・ルイビル」は、かつて北米最大の年間花火大会だった"},{"k":"symbol","zh":"州馬是純種馬，州鳥是北美紅雀，州花是一枝黃花","en":"The state horse is the Thoroughbred, the state bird the northern cardinal, and the state flower goldenrod.","ja":"州の馬はサラブレッド、州の鳥はショウジョウコウカンチョウ、州の花はアキノキリンソウ"},{"k":"record","zh":"○○德比和同場的橡樹大賽，是美國創辦以來年年舉行、歷史最悠久的大型賽事","en":"The ○○ Derby and ○○ Oaks are the oldest major US sporting events held every year since they began.","ja":"○○ダービーと○○オークスは、創設以来毎年開かれている米国最古の主要スポーツイベント"},{"k":"life","zh":"州內熟成中的波本酒桶超過1600萬個，是州人口的三倍多","en":"More than 16 million barrels of bourbon are aging in the state, over three times its human population.","ja":"州内で熟成中のバーボン樽は1600万を超え、州の人口の3倍以上だ"}],
"US-LA":[{"k":"people","zh":"爵士小號大師路易斯·阿姆斯壯出生於紐奧良","en":"Jazz trumpeter Louis Armstrong was born in New Orleans.","ja":"ジャズ・トランペット奏者ルイ・アームストロングはニューオーリンズ生まれ"},{"k":"sport","zh":"紐奧良聖徒隊2010年拿下第44屆超級盃，是隊史第一座冠軍","en":"The New Orleans Saints won Super Bowl XLIV in 2010, the first title in franchise history.","ja":"ニューオーリンズ・セインツは2010年の第44回スーパーボウルを制し、球団初の優勝を果たした"},{"k":"work","zh":"劇作《慾望街車》以紐奧良為舞台","en":"The play A Streetcar Named Desire is set in New Orleans.","ja":"戯曲『欲望という名の電車』はニューオーリンズが舞台"},{"k":"festival","zh":"紐奧良的嘉年華「懺悔星期二」，遊行花車會向群眾拋撒串珠項鍊","en":"During New Orleans Mardi Gras, parade floats toss strings of beads to the crowds.","ja":"ニューオーリンズのマルディグラでは、パレードの山車から観客へビーズの首飾りが投げられる"},{"k":"symbol","zh":"州旗上畫著鵜鶘媽媽和牠的雛鳥，1912年起就是州旗圖案","en":"A pelican and her young have appeared on the state flag since 1912.","ja":"州旗には1912年から、ペリカンの親子が描かれている"},{"k":"record","zh":"阿查法拉亞盆地是全美最大的沼澤濕地","en":"The Atchafalaya Basin is the largest swamp wetland in the United States.","ja":"アチャファラヤ盆地は全米最大の湿地・沼地だ"},{"k":"life","zh":"卡郡人的祖先，多是1755年起被英國從加拿大阿卡迪亞驅逐的法裔移民","en":"Cajuns largely descend from French Acadians expelled from Canada by the British starting in 1755.","ja":"ケイジャンの祖先の多くは、1755年からイギリスにカナダのアカディアを追われたフランス系住民だ"}],
"US-MA":[{"k":"people","zh":"富蘭克林常被聯想到費城，但他其實出生在○○。","en":"Benjamin Franklin is linked with Philadelphia, but he was actually born in ○○.","ja":"フィラデルフィアのイメージが強いフランクリンだが、実は○○生まれ。"},{"k":"people","zh":"繪本《戴帽子的貓》作者蘇斯博士，出生在○○的春田。","en":"Dr. Seuss, author of The Cat in the Hat, was born in Springfield, ○○.","ja":"絵本『キャット・イン・ザ・ハット』のドクター・スースは○○のスプリングフィールド生まれ。"},{"k":"sport","zh":"塞爾提克隊奪得 18 座 NBA 總冠軍，是聯盟史上最多。","en":"The Celtics have won 18 NBA championships, the most in league history.","ja":"セルティックスはNBA優勝18回で、リーグ史上最多。"},{"k":"record","zh":"芬威球場 1912 年啟用，是大聯盟現役最古老的球場。","en":"Fenway Park, opened in 1912, is the oldest ballpark still in use in Major League Baseball.","ja":"1912年開場のフェンウェイ・パークは、大リーグで現役最古の球場。"},{"k":"work","zh":"電影《大白鯊》是在○○的瑪莎葡萄園島拍攝的。","en":"The film Jaws was shot on Martha's Vineyard, ○○.","ja":"映画『ジョーズ』は○○のマーサズ・ヴィニヤード島で撮影された。"},{"k":"festival","zh":"因審巫案出名的塞勒姆，每年 10 月整個月都在過萬聖節。","en":"Salem, famous for its witch trials, celebrates Halloween for the whole month of October.","ja":"魔女裁判で知られるセイラムでは、毎年10月まるごとハロウィンを祝う。"},{"k":"origin","zh":"州名來自當地原住民族的族名，意思是「大山丘附近」。","en":"The name comes from a local Native people; it is often translated as near the great hill.","ja":"州名は地元の先住民族の名に由来し、「大きな丘のそば」と訳される。"},{"k":"symbol","zh":"○○的官方州貓是虎斑貓，州飲料是蔓越莓汁。","en":"The official state cat is the tabby, and the state beverage is cranberry juice.","ja":"州の猫はトラ猫、州の飲み物はクランベリージュース。"}],
"US-MD":[{"k":"people","zh":"棒球之神貝比·魯斯出生在巴爾的摩。","en":"Baseball legend Babe Ruth was born in Baltimore.","ja":"野球の神様ベーブ・ルースはボルチモア生まれ。"},{"k":"people","zh":"廢奴運動的哈莉特·塔布曼和道格拉斯，都在○○出生為奴。","en":"Abolitionists Harriet Tubman and Frederick Douglass were both born enslaved in ○○.","ja":"奴隷解放運動のハリエット・タブマンとダグラスは、ともに○○で奴隷として生まれた。"},{"k":"record","zh":"奧運金牌最多的泳將菲爾普斯，來自巴爾的摩。","en":"Michael Phelps, the most decorated Olympian of all time, is from Baltimore.","ja":"五輪の金メダル最多記録を持つ競泳のフェルプスはボルチモア出身。"},{"k":"sport","zh":"NFL 烏鴉隊的隊名取自愛倫坡的詩，吉祥物就叫 Edgar、Allan、Poe。","en":"The NFL's Ravens are named after Poe's poem, and their mascots are called Edgar, Allan and Poe.","ja":"NFLレイブンズの名はポーの詩から。マスコットの名前はエドガー、アラン、ポー。"},{"k":"work","zh":"歌舞電影《髮膠明星夢》的舞台是 1960 年代的巴爾的摩。","en":"The musical film Hairspray is set in 1960s Baltimore.","ja":"ミュージカル映画『ヘアスプレー』の舞台は1960年代のボルチモア。"},{"k":"origin","zh":"州名是為了紀念英王查理一世的王后亨麗埃塔·瑪麗亞。","en":"The state was named in honor of Henrietta Maria, queen of King Charles I.","ja":"州名は英国王チャールズ1世の王妃ヘンリエッタ・マリアにちなむ。"},{"k":"symbol","zh":"州貓是三花貓，毛色呼應殖民地領主卡爾弗特家族紋章的配色。","en":"The state cat is the calico, whose colors echo those of the Calvert family's coat of arms.","ja":"州の猫は三毛猫。毛色が領主カルバート家の紋章の配色に通じるため。"},{"k":"life","zh":"巴爾的摩港的「垃圾輪先生」靠水流和太陽能撈垃圾，還裝了一對大眼睛。","en":"Baltimore harbor's Mr. Trash Wheel scoops up trash using water and solar power, and has big googly eyes.","ja":"ボルチモア港の「ミスター・トラッシュ・ホイール」は水流と太陽光でごみを回収。大きな目玉付き。"}],
"US-ME":[{"k":"people","zh":"恐怖小說大師史蒂芬·金出生在○○，許多作品都以這裡為舞台。","en":"Horror master Stephen King was born in ○○, and many of his stories are set there.","ja":"ホラーの巨匠スティーヴン・キングは○○生まれ。多くの作品の舞台もここ。"},{"k":"work","zh":"電影《刺激1995》的肖申克監獄，設定就在○○。","en":"Shawshank prison in The Shawshank Redemption is set in ○○.","ja":"映画『ショーシャンクの空に』のショーシャンク刑務所は○○にある設定。"},{"k":"people","zh":"○○的瑪格麗特·蔡斯·史密斯，是第一位在參眾兩院都當過議員的女性。","en":"○○'s Margaret Chase Smith was the first woman to serve in both houses of Congress.","ja":"○○のマーガレット・チェイス・スミスは、上下両院で議員を務めた初の女性。"},{"k":"festival","zh":"15 歲少年格林伍德在○○發明了耳罩，小鎮法明頓每年 12 月為他遊行。","en":"Chester Greenwood invented earmuffs at 15 in ○○; the town of Farmington holds a parade for him each December.","ja":"15歳のグリーンウッドが○○で耳当てを発明。ファーミントンでは毎年12月にパレードがある。"},{"k":"symbol","zh":"州花其實不是花，而是白松的毬果和花穗。","en":"The state flower is not really a flower: it is the white pine cone and tassel.","ja":"州花は実は花ではなく、ストローブマツの松かさと花穂。"},{"k":"life","zh":"戶外品牌 L.L.Bean 在自由港的旗艦店，一年 365 天、24 小時營業。","en":"L.L.Bean's flagship campus in Freeport is open 24 hours a day, 365 days a year.","ja":"アウトドアブランドL.L.Beanのフリーポート本店は、365日24時間営業。"},{"k":"record","zh":"○○是全美最大的野生藍莓產地，州甜點就是野生藍莓派。","en":"○○ is the top US producer of wild blueberries, and its state dessert is wild blueberry pie.","ja":"○○は全米最大の野生ブルーベリー産地で、州のデザートもワイルドブルーベリーパイ。"},{"k":"life","zh":"甜甜圈中間的洞，據說是○○的船長漢森·格雷戈里想出來的。","en":"The hole in the doughnut is credited to Hansen Gregory, a sea captain from ○○.","ja":"ドーナツの穴は、○○の船長ハンセン・グレゴリーが考えたとされる。"}],
"US-MI":[{"k":"people","zh":"流行天后瑪丹娜出生於○○的貝城。","en":"Pop queen Madonna was born in Bay City, ○○.","ja":"ポップの女王マドンナは○○のベイシティ生まれ。"},{"k":"people","zh":"史提夫·汪達出生於薩吉諾。","en":"Stevie Wonder was born in Saginaw.","ja":"スティーヴィー・ワンダーはサギノー生まれ。"},{"k":"work","zh":"阿姆主演的電影《街頭痞子》，片名取自底特律的8英里路。","en":"Eminem's film 8 Mile is named after Detroit's 8 Mile Road.","ja":"エミネム主演の映画『8 Mile』の題名は、デトロイトの8マイル・ロードから。"},{"k":"sport","zh":"底特律紅翼隊拿過11座史丹利盃，城市因此自稱「冰球城」。","en":"The Detroit Red Wings have won 11 Stanley Cups, and the city calls itself \"Hockeytown.\"","ja":"デトロイト・レッドウィングスはスタンレー・カップを11回制し、町は「ホッケータウン」を名乗る。"},{"k":"festival","zh":"特拉弗斯城每年七月舉辦全國櫻桃節。","en":"Traverse City holds the National Cherry Festival every July.","ja":"トラバースシティでは毎年7月に全米チェリー祭りが開かれる。"},{"k":"origin","zh":"州名一般認為來自奧吉布瓦語的「大湖、大水」。","en":"The name is generally thought to come from an Ojibwe word meaning \"large lake\" or \"large water.\"","ja":"州名はオジブワ語の「大きな湖・大きな水」に由来するとされる。"},{"k":"symbol","zh":"州石佩托斯基石，其實是約3億5千萬年前的珊瑚化石。","en":"The state stone, the Petoskey stone, is actually fossil coral about 350 million years old.","ja":"州の石ペトスキー・ストーンは、実は約3億5千万年前のサンゴの化石。"},{"k":"life","zh":"下半島形狀像連指手套，當地人常舉起手掌比出自己住在哪裡。","en":"The Lower Peninsula is shaped like a mitten, so locals often hold up a hand to show where they live.","ja":"下半島はミトンの形で、地元の人は手のひらを掲げて自分の住む場所を示す。"}],
"US-MN":[{"k":"people","zh":"2016年諾貝爾文學獎得主巴布·狄倫出生於德盧斯。","en":"Bob Dylan, winner of the 2016 Nobel Prize in Literature, was born in Duluth.","ja":"2016年ノーベル文学賞のボブ・ディランはダルース生まれ。"},{"k":"people","zh":"歌手王子出生於明尼亞波利斯，一生都住在當地，錄音室「佩斯利公園」現為博物館。","en":"Prince was born in Minneapolis and lived there all his life; his Paisley Park studio is now a museum.","ja":"プリンスはミネアポリス生まれで生涯地元に住み、スタジオ「ペイズリー・パーク」は今は博物館。"},{"k":"people","zh":"《花生》漫畫、史努比的作者查爾斯·舒茲出生於明尼亞波利斯。","en":"Charles Schulz, creator of Peanuts and Snoopy, was born in Minneapolis.","ja":"『ピーナッツ』とスヌーピーの作者チャールズ・シュルツはミネアポリス生まれ。"},{"k":"work","zh":"電影《冰血暴》片名是鄰州的城市，但大部分劇情發生在○○。","en":"The film Fargo is named after a city in the next state, but most of it takes place in ○○.","ja":"映画『ファーゴ』の題名は隣州の町だが、物語の大半は○○で展開する。"},{"k":"sport","zh":"職棒雙城隊在1987年和1991年兩度拿下世界大賽冠軍。","en":"The Twins won the World Series in 1987 and 1991.","ja":"ツインズは1987年と1991年にワールドシリーズを制した。"},{"k":"festival","zh":"夏末的州博覽會以五花八門「插在棍子上的食物」聞名。","en":"The late-summer state fair is famous for its endless foods on a stick.","ja":"夏の終わりの州フェアは、串に刺したさまざまな食べ物で有名。"},{"k":"origin","zh":"州名來自達科他語，意思是「清澈的藍色湖水」或「混濁的水」。","en":"The name comes from Dakota words meaning \"clear blue water\" or \"cloudy water.\"","ja":"州名はダコタ語で「澄んだ青い水」または「濁った水」の意味。"},{"k":"symbol","zh":"州鳥是叫聲淒美的普通潛鳥，1961年選定。","en":"The state bird, chosen in 1961, is the common loon, known for its haunting call.","ja":"州の鳥は1961年に選ばれたハシグロアビ。物悲しい鳴き声で知られる。"}],
"US-MO":[{"k":"people","zh":"搖滾先驅查克·貝里出生於聖路易。","en":"Rock 'n' roll pioneer Chuck Berry was born in St. Louis.","ja":"ロックンロールの先駆者チャック・ベリーはセントルイス生まれ。"},{"k":"people","zh":"詩人瑪雅·安傑盧出生於聖路易。","en":"Poet Maya Angelou was born in St. Louis.","ja":"詩人マヤ・アンジェロウはセントルイス生まれ。"},{"k":"work","zh":"《湯姆歷險記》的小鎮以馬克·吐溫童年住的漢尼拔為原型。","en":"The town in The Adventures of Tom Sawyer is modeled on Hannibal, Mark Twain's boyhood home.","ja":"『トム・ソーヤーの冒険』の町は、マーク・トウェインが少年時代を過ごしたハンニバルがモデル。"},{"k":"work","zh":"Netflix影集《黑錢勝地》的舞台是奧沙克湖畔。","en":"The Netflix series Ozark is set around the Lake of the Ozarks.","ja":"Netflixドラマ『オザークへようこそ』の舞台はレイク・オブ・ジ・オザークス周辺。"},{"k":"sport","zh":"聖路易紅雀隊拿過11次世界大賽冠軍，是國家聯盟最多的球隊。","en":"The St. Louis Cardinals have won 11 World Series titles, the most of any National League team.","ja":"セントルイス・カージナルスはワールドシリーズを11回制し、ナショナル・リーグ最多。"},{"k":"life","zh":"百威啤酒的安海斯－布希釀酒廠位於聖路易，養著當招牌的克萊茲代爾大馬。","en":"Anheuser-Busch, maker of Budweiser, brews in St. Louis, home of its famous Clydesdale horses.","ja":"バドワイザーのアンハイザー・ブッシュはセントルイスにあり、看板のクライズデール馬を飼っている。"},{"k":"origin","zh":"州名源自原住民族名，意思是「擁有獨木舟的人」。","en":"The name comes from a Native people whose name means \"one who has dugout canoes.\"","ja":"州名は先住民の部族名に由来し、「丸木舟を持つ人」という意味。"},{"k":"symbol","zh":"州的代表動物是騾子，過去拓荒時期靠牠拉車運貨。","en":"The state animal is the mule, which hauled wagons in pioneer days.","ja":"州の動物はラバ。開拓時代に荷車を引いて活躍した。"}],
"US-MS":[{"k":"people","zh":"貓王艾維斯·普里斯萊1935年出生於○○的圖珀洛","en":"Elvis Presley was born in Tupelo, ○○, in 1935.","ja":"エルヴィス・プレスリーは1935年、○○のテューペロで生まれた"},{"k":"work","zh":"福克納小說裡的虛構郡「約克納帕塔法」，是以他住的拉法葉郡為原型","en":"Faulkner's fictional Yoknapatawpha County is based on Lafayette County, where he lived in Oxford.","ja":"フォークナーの小説の架空の郡ヨクナパトーファは、彼が住んだラファイエット郡がモデル"},{"k":"festival","zh":"「養殖鯰魚之都」貝爾佐尼每年4月舉辦世界鯰魚節，還會選出鯰魚小姐","en":"Belzoni, the 'Farm-Raised Catfish Capital of the World,' holds the World Catfish Festival every April, with a Miss Catfish pageant.","ja":"「養殖ナマズの首都」ベルゾーニでは毎年4月に世界ナマズ祭りが開かれ、ミス・キャットフィッシュも選ばれる"},{"k":"symbol","zh":"州的官方玩具是泰迪熊，2003年制定","en":"The official state toy is the teddy bear, adopted in 2003.","ja":"州の公式のおもちゃはテディベアで、2003年に制定された"},{"k":"record","zh":"1894年可口可樂第一次裝瓶，是在維克斯堡的一家糖果店","en":"Coca-Cola was first bottled in 1894 at a candy store in Vicksburg.","ja":"コカ・コーラが初めて瓶詰めされたのは1894年、ビックスバーグの菓子店だった"},{"k":"record","zh":"1964年世界首例把黑猩猩心臟移植到人體的手術，也在首府的同一家醫院進行","en":"In 1964 the same hospital in the capital performed the first transplant of a chimpanzee heart into a human.","ja":"1964年、同じ州都の病院で、チンパンジーの心臓を人に移植する世界初の手術が行われた"},{"k":"life","zh":"布偶之父吉姆·韓森在○○出生，他童年住的小鎮把一座橋命名為「彩虹連線」","en":"Muppets creator Jim Henson was born in ○○; Leland, his childhood town, named a bridge 'The Rainbow Connection.'","ja":"マペットの生みの親ジム・ヘンソンは○○生まれ。幼少期を過ごしたリーランドは橋を「レインボー・コネクション」と命名"}],
"US-MT":[{"k":"people","zh":"特技飛車手埃維爾·克尼維爾1938年生於○○的比尤特。","en":"Motorcycle daredevil Evel Knievel was born in Butte, ○○, in 1938.","ja":"バイクのスタントマン、イーブル・クニーブルは1938年に○○のビュートで生まれた。"},{"k":"people","zh":"拿過11座NBA總冠軍的教頭菲爾·傑克森，出生於○○的迪爾洛奇。","en":"Phil Jackson, who coached 11 NBA championship teams, was born in Deer Lodge, ○○.","ja":"NBAで11回優勝した名監督フィル・ジャクソンは、○○のディアロッジ生まれ。"},{"k":"record","zh":"1916年，○○選出美國史上第一位女性國會議員珍妮特·蘭金。","en":"In 1916 ○○ elected Jeannette Rankin, the first woman ever to serve in the US Congress.","ja":"1916年、○○は米国初の女性連邦議員ジャネット・ランキンを選出した。"},{"k":"work","zh":"電影《大河戀》講述一對兄弟在○○的米蘇拉一帶飛蠅釣、長大的故事。","en":"The film “A River Runs Through It” follows two brothers growing up and fly-fishing around Missoula, ○○.","ja":"映画『リバー・ランズ・スルー・イット』は、○○のミズーラでフライフィッシングをして育つ兄弟の物語。"},{"k":"work","zh":"影集《黃石》描寫一個家族為保住○○的巨大牧場而奮戰。","en":"The TV drama “Yellowstone” follows a family fighting to keep its huge ranch in ○○.","ja":"ドラマ『イエローストーン』は、○○の巨大な牧場を守ろうと闘う一家を描く。"},{"k":"symbol","zh":"○○的州花是苦根花，根是原住民的食物，當地山脈和河流都以它命名。","en":"○○'s state flower, the bitterroot, was a Native food; a mountain range and a river there are named after it.","ja":"○○の州花ビタールートは先住民の食料で、山脈や川の名前にもなっている。"},{"k":"origin","zh":"州名來自西班牙文「montaña」，意思是「山」或「多山的地方」。","en":"The name comes from the Spanish “montaña,” meaning “mountain” or “mountainous country.”","ja":"州名はスペイン語の「montaña」に由来し、「山」「山の多い土地」を意味する。"},{"k":"life","zh":"比尤特的柏克萊礦坑積滿含重金屬的酸性毒水，2016年數千隻雪雁誤降湖面而死。","en":"Butte's Berkeley Pit is filled with acidic, metal-laden water; in 2016 thousands of snow geese died after landing on it.","ja":"ビュートのバークレー・ピットは重金属を含む酸性の毒水で満ち、2016年には降り立った数千羽のハクガンが死んだ。"}],
"US-NC":[{"k":"people","zh":"籃球之神麥可·喬丹在○○的威明頓長大，大學打的是州立大學教堂山分校","en":"Michael Jordan grew up in Wilmington, ○○, and played college basketball at the state university in Chapel Hill.","ja":"マイケル・ジョーダンは○○のウィルミントンで育ち、大学は州立大学チャペルヒル校でプレーした"},{"k":"sport","zh":"NASCAR名人堂設在夏洛特，2010年開館","en":"The NASCAR Hall of Fame opened in Charlotte in 2010.","ja":"NASCARの殿堂は2010年にシャーロットで開館した"},{"k":"work","zh":"《安迪·格里菲斯秀》裡的小鎮梅貝里，原型是格里菲斯的故鄉芒特艾里","en":"Mayberry, the town in The Andy Griffith Show, is based on Mount Airy, Andy Griffith's hometown.","ja":"『アンディ・グリフィス・ショー』の町メイベリーは、グリフィスの故郷マウント・エアリーがモデル"},{"k":"festival","zh":"班納埃爾克每年10月辦毛毛蟲節，爬繩比賽的冠軍蟲負責預測冬天多冷","en":"Each October, Banner Elk's Woolly Worm Festival races caterpillars up strings; the winner forecasts the coming winter.","ja":"バナーエルクでは毎年10月に毛虫祭りがあり、ひもを登るレースの優勝毛虫が冬の寒さを占う"},{"k":"symbol","zh":"2005年州政府把捕蠅草定為官方食蟲植物，它野生只長在○○與鄰州的海岸平原","en":"In 2005 the state named the Venus flytrap its official carnivorous plant; it grows wild only on the coastal plain of ○○ and a neighbor.","ja":"2005年、州はハエトリグサを公式の食虫植物に指定した。野生では○○と隣州の海岸平野にしか生えない"},{"k":"record","zh":"比特摩爾莊園的主宅是全美最大的私人住宅，樓地板面積約1.66萬平方公尺","en":"Biltmore House is the largest privately owned house in the US, with about 16,600 m² of floor space.","ja":"ビルトモア・ハウスは全米最大の個人所有の邸宅で、床面積は約1万6600平方メートル"},{"k":"life","zh":"全美最大的研究園區「研究三角園」，就位在三所大學圍成的三角地帶","en":"Research Triangle Park, the largest research park in the US, sits within a triangle formed by three universities.","ja":"全米最大の研究団地リサーチ・トライアングル・パークは、3つの大学が作る三角形の中にある"},{"k":"life","zh":"櫻桃汽水Cheerwine名字有wine卻不含酒，1917年誕生，至今在索爾茲伯里生產","en":"Despite its name, Cheerwine is a non-alcoholic cherry soda; created in 1917, it is still made in Salisbury.","ja":"チアワインは名前と違ってノンアルコールのチェリーソーダ。1917年に生まれ、今もソールズベリーで作られている"}],
"US-ND":[{"k":"people","zh":"電影《變形金剛》系列的演員喬許·杜哈明出生在邁諾特。","en":"Actor Josh Duhamel of the Transformers films was born in Minot.","ja":"映画『トランスフォーマー』シリーズの俳優ジョシュ・デュアメルはマイノット生まれ。"},{"k":"people","zh":"拿下11座NBA總冠軍的名教練菲爾·傑克森，在威利斯頓長大。","en":"Phil Jackson, the coach who won 11 NBA titles, grew up in Williston.","ja":"NBAで11回優勝した名将フィル・ジャクソンはウィリストンで育った。"},{"k":"sport","zh":"州立大學野牛隊稱霸大學美式足球FCS級，2011–15年締造史上最長的五連霸。","en":"The state university's Bison rule FCS college football, with a record five straight national titles from 2011 to 2015.","ja":"州立大学バイソンズは大学アメフトFCSの絶対王者で、2011〜15年に史上最長の5連覇。"},{"k":"work","zh":"電影《冰血暴》片名取自州內最大城市法戈，但劇情幾乎都發生在明尼蘇達州。","en":"The film “Fargo” is named after the state's largest city, yet almost all of its story takes place in Minnesota.","ja":"映画『ファーゴ』は州最大の都市が題名だが、物語のほとんどはミネソタ州で起きる。"},{"k":"festival","zh":"邁諾特的北歐秋季節曾是北美最大的斯堪地那維亞節慶，2025年辦完最後一屆。","en":"Minot's Norsk Høstfest was North America's largest Scandinavian festival until its final edition in 2025.","ja":"マイノットの「ノルスク・ホストフェスト」は北米最大の北欧祭りだったが、2025年が最後の開催に。"},{"k":"symbol","zh":"榮譽州馬是諾科塔馬，祖先是西南部惡地裡的野馬群，1993年獲選。","en":"The honorary state equine is the Nokota horse, descended from feral herds of the southwestern Badlands; named in 1993.","ja":"名誉州馬はノコタ馬。南西部バッドランズの野生馬の子孫で、1993年に選ばれた。"},{"k":"record","zh":"魔法公路上的雕塑「飛翔之雁」高約34公尺，被金氏紀錄認證為世界最大的廢鐵雕塑。","en":"“Geese in Flight” on the Enchanted Highway, 110 ft tall, is Guinness's largest scrap-metal sculpture in the world.","ja":"エンチャンテッド・ハイウェイの「飛ぶガチョウ」は高さ約34mで、ギネス認定の世界最大の廃材彫刻。"},{"k":"life","zh":"來自俄國的德裔移民後代很多，炸肉餅弗萊施屈克勒是全州小鎮餐館的常見菜。","en":"Many residents descend from Germans from Russia, and the fried meat pie fleischkuekle is a staple of small-town diners.","ja":"ロシア出身のドイツ系移民の子孫が多く、揚げミートパイのフライシュキークレは町の食堂の定番。"}],
"US-NE":[{"k":"people","zh":"股神華倫·巴菲特出生於奧馬哈，波克夏公司總部至今仍設在當地。","en":"Investor Warren Buffett was born in Omaha, where Berkshire Hathaway is still headquartered.","ja":"投資家ウォーレン・バフェットはオマハ生まれで、バークシャー・ハサウェイの本社も今なお同地にある。"},{"k":"people","zh":"美國第38任總統福特出生在奧馬哈，出生時的名字是小萊斯利·林奇·金。","en":"Gerald Ford, the 38th U.S. president, was born in Omaha as Leslie Lynch King Jr.","ja":"第38代大統領ジェラルド・フォードはオマハ生まれで、出生時の名はレスリー・リンチ・キング・ジュニア。"},{"k":"sport","zh":"州立大學美式足球主場自1962年起連續超過400場門票售罄，是NCAA各項運動的紀錄。","en":"The state university's football stadium has sold out over 400 straight games since 1962, an NCAA record in any sport.","ja":"州立大学アメフトの本拠地は1962年から400試合以上連続で完売し、NCAA全競技の記録。"},{"k":"work","zh":"薇拉·凱瑟的小說《我的安東妮亞》描寫這片大草原上的拓荒移民生活。","en":"Willa Cather's novel “My Ántonia” portrays immigrant pioneers on these prairies.","ja":"ウィラ・キャザーの小説『マイ・アントニーア』は、この大草原の開拓移民の暮らしを描く。"},{"k":"festival","zh":"植樹節的發源地：1872年第一個植樹節，全州一天種下約百萬棵樹。","en":"Arbor Day was born here in 1872; about a million trees were planted across the state on the first one.","ja":"植樹の日の発祥地。1872年の第1回では州内で約100万本の木が植えられた。"},{"k":"symbol","zh":"州定汽水是1927年在哈斯廷斯發明的酷愛，當地每年8月還有「酷愛節」。","en":"The official state soft drink is Kool-Aid, invented in Hastings in 1927; the town holds “Kool-Aid Days” each August.","ja":"州の公式ソフトドリンクは1927年にヘイスティングスで生まれたクールエイド。毎年8月に記念祭もある。"},{"k":"origin","zh":"州名來自奧托族與奧馬哈族語「平坦的水」，指的是普拉特河。","en":"The name comes from Otoe and Omaha words meaning “flat water,” after the Platte River.","ja":"州名はオトー族とオマハ族の言葉で「平らな水」を意味し、プラット川を指す。"},{"k":"record","zh":"奧馬哈的亨利·多利動物園2014年被TripAdvisor評為「世界最佳動物園」。","en":"In 2014 TripAdvisor rated Omaha's Henry Doorly Zoo the best zoo in the world.","ja":"オマハのヘンリー・ドーリー動物園は2014年、トリップアドバイザーで「世界一の動物園」に選ばれた。"}],
"US-NH":[{"k":"people","zh":"美國第一位上太空的太空人謝帕德出生在○○，後來還在月球上打高爾夫。","en":"Alan Shepard, the first American in space, was born in ○○ and later hit golf balls on the Moon.","ja":"アメリカ人初の宇宙飛行士シェパードは○○生まれ。のちに月面でゴルフをした。"},{"k":"people","zh":"《達文西密碼》作者丹·布朗出生在○○的埃克塞特。","en":"Dan Brown, author of The Da Vinci Code, was born in Exeter, ○○.","ja":"『ダ・ヴィンチ・コード』の作者ダン・ブラウンは○○のエクセター生まれ。"},{"k":"life","zh":"保鮮盒特百惠（Tupperware）的發明人塔珀，出生在○○的柏林鎮。","en":"Earl Tupper, inventor of Tupperware, was born in Berlin, ○○.","ja":"タッパーウェアを発明したアール・タッパーは○○のベルリン生まれ。"},{"k":"work","zh":"劇作《小城風光》的虛構小鎮，部分以○○的彼得伯勒為藍本。","en":"Grover's Corners in the play Our Town is partly based on Peterborough, ○○.","ja":"戯曲『わが町』の架空の町は、○○のピーターボロがモデルの一つ。"},{"k":"festival","zh":"每年 6 月的拉科尼亞機車週始於 1916 年，曾是北美最大的機車聚會。","en":"Laconia Motorcycle Week, held each June since 1916, was once North America's largest biker gathering.","ja":"毎年6月のラコニア・モーターサイクル・ウィークは1916年に始まり、かつて北米最大のバイク集会だった。"},{"k":"origin","zh":"州名來自英格蘭南部的漢普郡。","en":"The state is named after the English county of Hampshire.","ja":"州名はイングランド南部のハンプシャー州に由来する。"},{"k":"symbol","zh":"州鳥是紫朱雀、州花是紫丁香，兩個都是紫色的。","en":"The state bird is the purple finch and the state flower the purple lilac: both purple.","ja":"州鳥はムラサキマシコ、州花はムラサキハシドイ（ライラック）。どちらも紫。"},{"k":"record","zh":"拉科尼亞的 Funspot 被稱為世界最大的電玩遊樂場。","en":"Funspot in Laconia is described as the world's largest video arcade.","ja":"ラコニアのファンスポットは、世界最大のゲームセンターとされる。"}],
"US-NJ":[{"k":"people","zh":"人稱「老闆」的布魯斯·史普林斯汀出身○○，許多歌都在唱這裡。","en":"Bruce Springsteen, The Boss, comes from ○○, and many of his songs are about it.","ja":"「ボス」ことブルース・スプリングスティーンは○○出身。多くの歌でこの地を歌う。"},{"k":"people","zh":"傳奇歌手法蘭克·辛納屈出生在○○的霍博肯。","en":"Legendary singer Frank Sinatra was born in Hoboken, ○○.","ja":"伝説の歌手フランク・シナトラは○○のホーボーケン生まれ。"},{"k":"work","zh":"影集《黑道家族》裡黑幫老大東尼·索波諾一家住在○○。","en":"In The Sopranos, mob boss Tony Soprano and his family live in ○○.","ja":"ドラマ『ザ・ソプラノズ』のマフィアのボス、トニー一家は○○に住んでいる。"},{"k":"symbol","zh":"州恐龍鴨嘴龍的化石在海頓菲爾德出土，是世界第一具組裝展示的恐龍骨架。","en":"The state dinosaur, Hadrosaurus, found in Haddonfield, became the first mounted dinosaur skeleton ever.","ja":"州の恐竜ハドロサウルスはハドンフィールドで発掘され、世界初の組み立て展示された恐竜骨格に。"},{"k":"festival","zh":"第一屆美國小姐選美，1921 年在大西洋城舉行。","en":"The first Miss America pageant was held in Atlantic City in 1921.","ja":"第1回ミス・アメリカは1921年、アトランティックシティで開かれた。"},{"k":"origin","zh":"州名來自英吉利海峽上的一座海峽群島。","en":"The state is named after one of the Channel Islands in the English Channel.","ja":"州名はイギリス海峡に浮かぶチャンネル諸島の一つに由来する。"},{"k":"record","zh":"愛迪生實驗室所在的門洛帕克，克里斯蒂街號稱世界第一條用電燈照明的街道。","en":"Christie Street in Menlo Park, home of Edison's lab, is said to be the world's first street lit by electric light.","ja":"エジソンの研究所があったメンローパークのクリスティ通りは、世界初の電灯で照らされた通りとされる。"},{"k":"life","zh":"1870 年，大西洋城蓋了全美第一條海濱木棧道。","en":"In 1870 Atlantic City built the first boardwalk in the United States.","ja":"1870年、アトランティックシティにアメリカ初の海辺のボードウォークが造られた。"}],
"US-NM":[{"k":"people","zh":"藝名取自科羅拉多州首府的歌手約翰·丹佛，其實出生在羅斯威爾。","en":"Singer John Denver, whose stage name came from Colorado's capital, was actually born in Roswell.","ja":"コロラド州の州都から芸名を取った歌手ジョン・デンバーは、実はロズウェル生まれ。"},{"k":"people","zh":"畫家喬治亞·歐姬芙晚年定居阿比丘，常畫這裡的荒漠和白骨。","en":"Painter Georgia O'Keeffe settled in Abiquiú, often painting its desert landscapes and bleached bones.","ja":"画家ジョージア・オキーフはアビキューに移り住み、砂漠の風景や白骨をよく描いた。"},{"k":"sport","zh":"小聯盟球隊阿布奎基同位素隊，隊名取自《辛普森家庭》裡的虛構球隊。","en":"The minor-league Albuquerque Isotopes took their name from a fictional team on “The Simpsons.”","ja":"マイナーリーグのアルバカーキ・アイソトープスは『ザ・シンプソンズ』の架空球団が名の由来。"},{"k":"work","zh":"影集《絕命毒師》以阿布奎基為舞台，劇中的化學老師在這裡走上製毒之路。","en":"“Breaking Bad” is set in Albuquerque, where a chemistry teacher turns drug maker.","ja":"ドラマ『ブレイキング・バッド』はアルバカーキが舞台で、化学教師が麻薬製造に手を染める。"},{"k":"festival","zh":"阿布奎基國際熱氣球節每年10月有500多顆熱氣球升空，是世界最大的熱氣球節。","en":"Each October the Albuquerque International Balloon Fiesta launches 500-plus balloons—the world's largest balloon festival.","ja":"毎年10月のアルバカーキ国際バルーン・フィエスタは500機以上が飛ぶ世界最大の気球祭。"},{"k":"symbol","zh":"州鳥是走鵑，也就是卡通「嗶嗶鳥」的原型。","en":"The state bird is the greater roadrunner, the real-life model for the cartoon Road Runner.","ja":"州の鳥はオオミチバシリで、アニメ「ロード・ランナー」のモデル。"},{"k":"symbol","zh":"2023年起，官方的「州定香氣」是烘烤青辣椒的香味。","en":"Since 2023, the official state aroma has been the smell of roasting green chile.","ja":"2023年から、州の公式の「香り」は青唐辛子をローストする香り。"},{"k":"record","zh":"首府的聖米格爾教堂約建於1610年，被視為美國最古老的教堂。","en":"The capital's San Miguel Mission, built around 1610, is considered the oldest church in the U.S.","ja":"州都のサン・ミゲル教会は1610年頃の建造で、米国最古の教会とされる。"}],
"US-NV":[{"k":"people","zh":"網球天王阿格西1970年在○○最大城出生、長大。","en":"Tennis great Andre Agassi was born in 1970 and raised in ○○'s largest city.","ja":"テニスの名選手アンドレ・アガシは1970年、○○最大の都市で生まれ育った。"},{"k":"people","zh":"殺手樂團（The Killers）和謎幻樂團（Imagine Dragons）都是在○○最大城組成的。","en":"The Killers and Imagine Dragons were both formed in ○○'s largest city.","ja":"ザ・キラーズとイマジン・ドラゴンズは、どちらも○○最大の都市で結成された。"},{"k":"work","zh":"影集《CSI犯罪現場》的鑑識小組，就在○○最大城辦案。","en":"The forensic team in “CSI: Crime Scene Investigation” works in ○○'s largest city.","ja":"ドラマ『CSI:科学捜査班』の鑑識チームは、○○最大の都市で捜査している。"},{"k":"festival","zh":"火人祭每年夏末在黑石沙漠舉行，數萬人搭起臨時城市，最後燒掉巨大木人。","en":"Each late summer, Burning Man builds a temporary city in the Black Rock Desert and burns a giant wooden man.","ja":"毎年夏の終わり、ブラックロック砂漠のバーニングマンでは仮設の街を作り、巨大な木の人形を燃やす。"},{"k":"sport","zh":"NFL突擊者隊在2020年從加州奧克蘭搬到○○。","en":"The NFL's Raiders moved from Oakland, California, to ○○ in 2020.","ja":"NFLのレイダースは2020年、カリフォルニア州オークランドから○○へ移転した。"},{"k":"origin","zh":"州名來自西班牙文，意思是「積雪的」，取自州西側山脈的名字。","en":"The name comes from the Spanish word for “snow-covered,” borrowed from the mountain range to the west.","ja":"州名はスペイン語で「雪に覆われた」の意味。西側の山脈の名前から取られた。"},{"k":"symbol","zh":"2025年，州議會把巴斯克移民愛喝的皮康潘趣定為○○的官方調酒。","en":"In 2025 lawmakers made the Picon Punch, beloved by Basque immigrants, ○○'s official state cocktail.","ja":"2025年、州議会はバスク系移民に愛されたピコン・パンチを○○の公式カクテルに定めた。"},{"k":"life","zh":"雷諾市大街的拱門上寫著「世界最大的小城市」。","en":"An arch over Reno's main street proclaims it “The Biggest Little City in the World.”","ja":"リノの大通りのアーチには「世界一大きな小さな街」と書かれている。"}],
"US-NY":[{"k":"sport","zh":"洋基隊拿過 27 座世界大賽冠軍，是大聯盟最多。","en":"The Yankees have won 27 World Series titles, the most in Major League Baseball.","ja":"ヤンキースはワールドシリーズ優勝27回で、大リーグ最多。"},{"k":"festival","zh":"梅西百貨感恩節大遊行從 1924 年開始，每年在曼哈頓舉行。","en":"The Macy's Thanksgiving Day Parade has marched through Manhattan every year since 1924.","ja":"メイシーズ・サンクスギビング・デー・パレードは1924年から毎年マンハッタンで開かれている。"},{"k":"festival","zh":"1969 年的胡士托音樂節，其實是在貝瑟爾的一座農場舉辦。","en":"The 1969 Woodstock festival was actually held on a dairy farm in Bethel.","ja":"1969年のウッドストック・フェスティバルは、実はベセルの農場で開かれた。"},{"k":"work","zh":"小說《大亨小傳》裡蓋茲比的豪宅派對，發生在○○的長島。","en":"Gatsby's lavish mansion parties in The Great Gatsby take place on Long Island, ○○.","ja":"小説『グレート・ギャツビー』の豪邸パーティーの舞台は○○のロングアイランド。"},{"k":"origin","zh":"州名紀念一位英國公爵，他後來成為英王詹姆士二世。","en":"The state is named for an English duke who later became King James II.","ja":"州名は、のちの英国王ジェームズ2世となったイギリスの公爵にちなむ。"},{"k":"symbol","zh":"州的官方點心是優格，州水果是蘋果。","en":"The official state snack is yogurt, and the state fruit is the apple.","ja":"州の公式スナックはヨーグルト、州の果物はリンゴ。"},{"k":"record","zh":"時代廣場的跨年降球從 1907 年延續至今。","en":"The Times Square New Year's Eve ball drop has taken place since 1907.","ja":"タイムズスクエアの年越しボールドロップは1907年から続いている。"},{"k":"people","zh":"流行天后 Lady Gaga 出生在○○的曼哈頓。","en":"Pop star Lady Gaga was born in Manhattan, ○○.","ja":"ポップスターのレディー・ガガは○○のマンハッタン生まれ。"}],
"US-OH":[{"k":"people","zh":"發明家愛迪生出生在州北部的米蘭小鎮。","en":"Inventor Thomas Edison was born in the small town of Milan in the north of the state.","ja":"発明王エジソンは州北部の小さな町ミランで生まれた。"},{"k":"people","zh":"NBA球星雷霸龍·詹姆斯出生於阿克倫，高中時就被稱為「天選之人」。","en":"NBA star LeBron James was born in Akron and was dubbed “The Chosen One” while still in high school.","ja":"NBAスターのレブロン・ジェームズはアクロン生まれで、高校時代から「選ばれし者」と呼ばれた。"},{"k":"sport","zh":"1869年辛辛那提紅長襪隊成為史上第一支全員職業的棒球隊。","en":"In 1869 the Cincinnati Red Stockings became the first fully professional baseball team.","ja":"1869年、シンシナティ・レッドストッキングスが史上初の完全プロ野球チームになった。"},{"k":"work","zh":"1983年聖誕經典電影《聖誕故事》的主角家在克里夫蘭，現已改成博物館。","en":"The house from the 1983 holiday classic “A Christmas Story” is in Cleveland and is now a museum.","ja":"1983年のクリスマス映画『クリスマス・ストーリー』の家はクリーブランドにあり、今は博物館。"},{"k":"festival","zh":"雙胞胎鎮每年8月舉辦「雙胞胎節」，是世界最大的年度雙胞胎聚會。","en":"Twinsburg's Twins Days, held every August, is the world's largest annual gathering of twins.","ja":"ツインズバーグで毎年8月に開く「ツインズ・デイズ」は世界最大の双子の集い。"},{"k":"origin","zh":"州名來自塞內卡語「好河、大河」，指的是同名的那條河。","en":"The name comes from a Seneca word meaning “good river” or “great river,” for the river of the same name.","ja":"州名はセネカ語の「良い川・大きな川」に由来し、同名の川を指す。"},{"k":"symbol","zh":"州定水果是番茄，州定原生水果則是北美特有的巴婆果。","en":"The state fruit is the tomato, and the state native fruit is the pawpaw.","ja":"州の果物はトマト、州の在来果物は北米原産のポーポー。"},{"k":"life","zh":"州旗有官方摺法，要剛好摺17次，呼應它是第17個加入聯邦的州。","en":"The flag has an official folding method of exactly 17 folds, echoing its status as the 17th state.","ja":"州旗には公式のたたみ方があり、17番目の州にちなんでちょうど17回折る。"}],
"US-OK":[{"k":"people","zh":"演員布萊德·彼特出生在肖尼。","en":"Actor Brad Pitt was born in Shawnee.","ja":"俳優ブラッド・ピットはショーニー生まれ。"},{"k":"people","zh":"以《這是你的土地》聞名的民謠歌手伍迪·蓋瑟瑞，出生於奧克馬。","en":"Folk singer Woody Guthrie, of “This Land Is Your Land,” was born in Okemah.","ja":"「わが祖国」で知られるフォーク歌手ウディ・ガスリーはオキーマ生まれ。"},{"k":"sport","zh":"NBA雷霆隊的前身是西雅圖超音速，2008年遷來，是州內唯一的大聯盟球隊。","en":"The NBA's Thunder, formerly the Seattle SuperSonics, moved here in 2008; it's the state's only major-league team.","ja":"NBAのサンダーは元シアトル・スーパーソニックスで2008年に移転、州唯一のメジャー球団。"},{"k":"work","zh":"小說《小教父》（The Outsiders）的舞台是塔爾薩。","en":"S. E. Hinton's novel “The Outsiders” is set in Tulsa.","ja":"S・E・ヒントンの小説『アウトサイダーズ』の舞台はタルサ。"},{"k":"festival","zh":"艾爾雷諾自1988年起，每年5月第一個週六舉辦「炸洋蔥漢堡節」。","en":"Since 1988, El Reno has held Fried Onion Burger Day on the first Saturday of May.","ja":"エルリノでは1988年から毎年5月第1土曜に「フライドオニオンバーガーの日」祭りを開く。"},{"k":"record","zh":"比佛鎮1970年帶動「丟牛糞餅」比賽風潮，紀錄是2001年擲出的約56.5公尺。","en":"Beaver popularized cow chip throwing in 1970; the record toss, from 2001, is 185 ft 5 in (56.5 m).","ja":"ビーバーの町は1970年に牛ふん投げを広め、2001年の記録は約56.5m。"},{"k":"origin","zh":"州名來自喬克托族語，意思是「紅色的人」。","en":"The name comes from Choctaw words meaning “red people.”","ja":"州名はチョクトー語で「赤い人々」を意味する言葉に由来する。"},{"k":"symbol","zh":"州歌就是同名百老匯音樂劇的主題曲。","en":"The state song is the title number from the Broadway musical of the same name.","ja":"州歌は同名のブロードウェイ・ミュージカルの主題歌。"}],
"US-OR":[{"k":"people","zh":"生於波特蘭的鮑林，是唯一兩度獨得諾貝爾獎（化學、和平）的人。","en":"Portland-born Linus Pauling is the only person to win two unshared Nobel Prizes, in chemistry and peace.","ja":"ポートランド生まれのライナス・ポーリングは、ノーベル化学賞と平和賞を単独で受けた唯一の人物。"},{"k":"people","zh":"Nike共同創辦人菲爾·奈特1938年生於波特蘭，大學時是田徑中長跑選手。","en":"Nike co-founder Phil Knight was born in Portland in 1938 and ran middle distance in college.","ja":"ナイキ共同創業者フィル・ナイトは1938年ポートランド生まれ。大学では中距離走の選手だった。"},{"k":"work","zh":"電影《七寶奇謀》以海港小鎮阿斯托利亞為舞台，片中的房子成了觀光景點。","en":"“The Goonies” is set in the port town of Astoria, where the film's house became a tourist spot.","ja":"『グーニーズ』の舞台は港町アストリアで、劇中の家は観光名所になった。"},{"k":"sport","zh":"尤金的海沃德田徑場在2022年舉辦世界田徑錦標賽，是這項賽事首次在美國舉行。","en":"Eugene's Hayward Field hosted the 2022 World Athletics Championships, the first ever held in the US.","ja":"ユージーンのヘイワード・フィールドは2022年、米国初となる世界陸上を開催した。"},{"k":"festival","zh":"波特蘭玫瑰節自1907年起每年6月舉行，波特蘭也因此被稱為「玫瑰之城」。","en":"Portland's Rose Festival has been held every June since 1907; the city is nicknamed the “City of Roses.”","ja":"ポートランドのローズ・フェスティバルは1907年から毎年6月開催。街は「バラの都」と呼ばれる。"},{"k":"origin","zh":"州名由來至今沒有定論，其中一說來自法文「ouragan（暴風）」。","en":"The name's origin is still debated; one theory links it to the French “ouragan,” meaning hurricane.","ja":"州名の由来には今も定説がなく、フランス語の「ouragan（暴風）」から来たという説もある。"},{"k":"symbol","zh":"州石是「雷蛋」，外表像普通石頭，剖開後裡面是瑪瑙或水晶。","en":"The state rock is the thunderegg, a plain-looking stone that reveals agate or crystal inside when cut.","ja":"州の石はサンダーエッグ。見た目は普通の石だが、割ると中にメノウや水晶が現れる。"},{"k":"life","zh":"○○從1951年起禁止自助加油，直到2023年才部分開放。","en":"○○ banned self-service gas pumping from 1951 until 2023, when it was partly allowed.","ja":"○○では1951年からセルフ給油が禁止され、2023年にようやく一部解禁された。"}],
"US-PA":[{"k":"people","zh":"流行天后泰勒絲1989年出生於○○的西雷丁","en":"Pop star Taylor Swift was born in West Reading, ○○, in 1989.","ja":"ポップスターのテイラー・スウィフトは1989年、○○のウェスト・レディングで生まれた"},{"k":"work","zh":"電影《洛基》主角跑上費城美術館階梯的場景，讓那段階梯被稱為「洛基階梯」","en":"Rocky's run up the Philadelphia Museum of Art steps made them famous as the 'Rocky Steps.'","ja":"映画『ロッキー』で主人公が駆け上がったフィラデルフィア美術館の階段は「ロッキー・ステップ」と呼ばれる"},{"k":"festival","zh":"費城每年元旦舉行化妝大遊行「默默斯遊行」，1901年起從未中斷，是全美持續最久的民俗遊行","en":"Philadelphia's Mummers Parade, held every New Year's Day since 1901, is the longest-running continuous folk parade in the US.","ja":"毎年元日のフィラデルフィアの「ママーズ・パレード」は1901年から続く、全米で最も長く続く民俗パレード"},{"k":"symbol","zh":"州犬是大丹犬，州昆蟲是螢火蟲","en":"The state dog is the Great Dane, and the state insect is the firefly.","ja":"州の犬はグレート・デーン、州の昆虫はホタル"},{"k":"record","zh":"費城動物園1859年獲准設立，被稱為美國第一座真正的動物園","en":"Chartered in 1859, the Philadelphia Zoo is called the first true zoo in the United States.","ja":"1859年に設立認可を受けたフィラデルフィア動物園は、アメリカ初の本格的な動物園とされる"},{"k":"life","zh":"所謂「○○荷蘭人」其實是德裔移民，Dutch源自德語系的Deitsch（德意志）","en":"The so-called '○○ Dutch' are actually of German descent; 'Dutch' comes from Deitsch, meaning German.","ja":"「○○・ダッチ」と呼ばれる人々は実はドイツ系で、「ダッチ」はドイツ語系の Deitsch に由来する"}],
"US-RI":[{"k":"people","zh":"1 美元鈔票上的華盛頓肖像，原畫作者吉爾伯特·斯圖爾特生於○○。","en":"Gilbert Stuart, painter of the Washington portrait on the one-dollar bill, was born in ○○.","ja":"1ドル札のワシントン像の原画を描いたギルバート・スチュアートは○○生まれ。"},{"k":"people","zh":"克蘇魯神話之父洛夫克拉夫特出生在○○，一生大多住在這裡。","en":"H. P. Lovecraft, father of the Cthulhu Mythos, was born in ○○ and lived there most of his life.","ja":"クトゥルフ神話の生みの親ラヴクラフトは○○生まれで、生涯の大半をここで過ごした。"},{"k":"work","zh":"動畫《蓋酷家庭》的虛構城市寬侯格，設定就在○○。","en":"Quahog, the fictional town of Family Guy, is set in ○○.","ja":"アニメ『ファミリー・ガイ』の架空の町クアホッグは○○にある設定。"},{"k":"sport","zh":"美國網球公開賽的前身，1881 年首次在新港舉辦。","en":"The first US National Championships, forerunner of the US Open tennis, were held in Newport in 1881.","ja":"全米オープンテニスの前身大会は、1881年にニューポートで初開催された。"},{"k":"origin","zh":"州名一說是探險家韋拉札諾把外海小島比作希臘愛琴海的一座島。","en":"One theory: explorer Verrazzano likened an island here to a Greek island in the Aegean.","ja":"一説では、探検家ヴェラッツァーノが沖の島をエーゲ海のギリシャの島になぞらえたことから。"},{"k":"record","zh":"布朗大學是美國第一所不論宗教信仰都收學生的大學。","en":"Brown University was the first US college to accept students regardless of religion.","ja":"ブラウン大学は、宗教を問わず学生を受け入れたアメリカ初の大学。"},{"k":"symbol","zh":"州飲料是咖啡牛奶，用咖啡糖漿加牛奶調成，據說源自州內的黑石河谷。","en":"The state drink is coffee milk, made by mixing coffee syrup into milk; it is said to have originated in the state's Blackstone Valley.","ja":"州の飲み物はコーヒー牛乳。コーヒーシロップを牛乳で割ったもので、州内のブラックストーン・バレー発祥とされる。"}],
"US-SC":[{"k":"people","zh":"「靈魂樂教父」詹姆斯·布朗1933年出生於○○的巴恩韋爾","en":"James Brown, the 'Godfather of Soul,' was born in Barnwell, ○○, in 1933.","ja":"「ソウルのゴッドファーザー」ジェームス・ブラウンは1933年、○○のバーンウェルで生まれた"},{"k":"people","zh":"以上翹小號聞名的爵士樂手迪吉·葛拉斯彼，1917年生於○○的切勞","en":"Jazz trumpeter Dizzy Gillespie, famous for his bent trumpet, was born in Cheraw, ○○, in 1917.","ja":"曲がったトランペットで知られるジャズ奏者ディジー・ガレスピーは、1917年に○○のチェローで生まれた"},{"k":"sport","zh":"達靈頓賽道號稱「難以馴服的賽道」，1950年首次舉辦南方500大賽","en":"Darlington Raceway, 'The Track Too Tough to Tame,' first hosted the Southern 500 in 1950.","ja":"「手なずけられないコース」ダーリントン・レースウェイは、1950年に初めてサザン500を開いた"},{"k":"work","zh":"歌劇《波吉與貝絲》的舞台「鯰魚街」，以查爾斯頓海濱的一處住宅為原型","en":"Porgy and Bess is set on Catfish Row, modeled on Cabbage Row on Charleston's waterfront.","ja":"オペラ『ポーギーとベス』の舞台キャットフィッシュ・ロウは、チャールストンの海辺の長屋がモデル"},{"k":"festival","zh":"查爾斯頓的斯波萊托藝術節1977年由作曲家梅諾第創辦，每年春末連辦17天","en":"Charleston's Spoleto Festival USA, founded in 1977 by composer Gian Carlo Menotti, runs 17 days each late spring.","ja":"チャールストンのスポレート・フェスティバルUSAは1977年に作曲家メノッティが創設、毎年晩春に17日間開かれる"},{"k":"symbol","zh":"1776年用矮棕櫚木蓋的堡壘吸收了英艦砲彈，矮棕櫚從此成為州的象徵","en":"In 1776, a fort built of palmetto logs absorbed British cannon fire, making the palmetto the state's symbol.","ja":"1776年、パルメットヤシの丸太で築いた砦が英艦の砲弾を吸収し、パルメットは州の象徴となった"},{"k":"record","zh":"查爾斯頓博物館1773年創立，是美國最古老的博物館","en":"Founded in 1773, the Charleston Museum is the oldest museum in the United States.","ja":"1773年創設のチャールストン博物館は、アメリカ最古の博物館だ"},{"k":"life","zh":"水煮花生是州的官方零食","en":"Boiled peanuts are the official state snack.","ja":"ゆでピーナッツは州の公式スナックだ"}],
"US-SD":[{"k":"people","zh":"知名新聞主播湯姆·布羅考出生在韋伯斯特。","en":"Longtime network news anchor Tom Brokaw was born in Webster.","ja":"著名なニュースキャスター、トム・ブロコウはウェブスター生まれ。"},{"k":"people","zh":"拉科塔族領袖坐牛出生在今日州內的大河沿岸。","en":"Lakota leader Sitting Bull was born along the Grand River, in what is now this state.","ja":"ラコタ族の指導者シッティング・ブルは、現在の州内を流れるグランド川沿いで生まれた。"},{"k":"festival","zh":"斯特吉斯每年8月的機車大會，會讓數十萬名騎士湧進這座小鎮。","en":"Every August the Sturgis Motorcycle Rally brings hundreds of thousands of riders into the small town.","ja":"毎年8月のスタージス・モーターサイクル・ラリーには、数十万人のライダーが小さな町に集まる。"},{"k":"work","zh":"《草原上的小木屋》作者羅蘭·英格斯·懷德一家曾住在德斯梅特，好幾集以此為舞台。","en":"Laura Ingalls Wilder's family lived in De Smet, the setting of several of her “Little House” books.","ja":"『大草原の小さな家』の作者ローラ・インガルス・ワイルダー一家はデ・スメットに住み、数作の舞台になった。"},{"k":"work","zh":"凱文·科斯納自導自演的電影《與狼共舞》，大部分在州內拍攝。","en":"Kevin Costner's “Dances with Wolves” was filmed largely in the state.","ja":"ケビン・コスナー監督・主演の『ダンス・ウィズ・ウルブズ』は大部分が州内で撮影された。"},{"k":"symbol","zh":"州鳥環頸雉其實是亞洲原生的外來種，1900年代初才被引進。","en":"The state bird, the ring-necked pheasant, is actually an Asian import brought in during the early 1900s.","ja":"州の鳥コウライキジは実はアジア原産で、1900年代初めに持ち込まれた外来種。"},{"k":"symbol","zh":"官方「州定點心」是炸或烤的肉丁串奇斯利克，州定甜點則是德式水果派。","en":"The official “state nosh” is chislic, cubed fried or grilled meat; the state dessert is kuchen.","ja":"公式の「州の軽食」は角切り肉を揚げたり焼いたりしたチスリック、州のデザートはクーヘン。"},{"k":"record","zh":"霍姆斯特克金礦深約2,400公尺，曾是西半球最深的金礦，如今改建成地下實驗室。","en":"The Homestake gold mine, about 8,000 ft deep, was the Western Hemisphere's deepest; it's now an underground lab.","ja":"ホームステイク金鉱は深さ約2400mで西半球一深い金鉱だった。今は地下研究所になっている。"}],
"US-TN":[{"k":"people","zh":"鄉村天后桃莉·巴頓出生在○○的山區，家中共有12個兄弟姊妹。","en":"Country queen Dolly Parton was born in the mountains of ○○, one of 12 children.","ja":"カントリーの女王ドリー・パートンは○○の山あいで12人きょうだいの一人として生まれた。"},{"k":"people","zh":"影帝摩根·費里曼出生於曼非斯。","en":"Oscar-winning actor Morgan Freeman was born in Memphis.","ja":"アカデミー賞俳優モーガン・フリーマンはメンフィス生まれ。"},{"k":"sport","zh":"NBA灰熊隊原本在加拿大溫哥華，2001年搬到曼非斯。","en":"The NBA's Grizzlies started in Vancouver, Canada, and moved to Memphis in 2001.","ja":"NBAのグリズリーズはカナダのバンクーバーで誕生し、2001年にメンフィスへ移転した。"},{"k":"festival","zh":"邦納魯音樂節每年夏天在曼徹斯特的農場舉辦，樂迷連續幾天露營聽音樂。","en":"The Bonnaroo festival is held each summer on a farm in Manchester, where fans camp for days of music.","ja":"ボナルー・フェスは毎年夏にマンチェスターの農場で開かれ、ファンは数日間キャンプして音楽を楽しむ。"},{"k":"origin","zh":"州名源自切羅基族的城鎮「Tanasi」。","en":"The state's name comes from Tanasi, a Cherokee town.","ja":"州名はチェロキー族の町「タナシ」に由来する。"},{"k":"symbol","zh":"藍草名曲〈Rocky Top〉是○○的官方州歌之一，而○○的州歌多達十幾首。","en":"The bluegrass hit \"Rocky Top\" is one of ○○'s official state songs, and ○○ has more than a dozen of them.","ja":"ブルーグラスの名曲「ロッキー・トップ」は○○の州歌の一つ。○○の州歌は十数曲もある。"},{"k":"work","zh":"電影《攻其不備》改編自曼非斯一名高中美式足球員被富裕家庭收養的真實故事。","en":"The film The Blind Side is based on the true story of a Memphis high school football player adopted by a wealthy family.","ja":"映画『しあわせの隠れ場所』は、裕福な家族に引き取られたメンフィスの高校アメフト選手の実話。"},{"k":"record","zh":"大奧普里從1925年播出至今，是美國歷史最悠久的廣播節目。","en":"The Grand Ole Opry has aired since 1925, making it the longest-running radio broadcast in US history.","ja":"グランド・オール・オープリーは1925年から続く、米国史上最も長寿のラジオ番組。"}],
"US-TX":[{"k":"people","zh":"天后碧昂絲在休士頓出生長大。","en":"Beyoncé was born and raised in Houston.","ja":"歌姫ビヨンセはヒューストンで生まれ育った。"},{"k":"people","zh":"二戰盟軍統帥、後來的艾森豪總統出生在丹尼森。","en":"WWII Allied commander and later president Dwight D. Eisenhower was born in Denison.","ja":"第二次大戦の連合軍最高司令官で後の大統領アイゼンハワーはデニソン生まれ。"},{"k":"sport","zh":"國家美式足球聯盟的達拉斯牛仔隊，有「美國之隊」的稱號。","en":"The NFL's Dallas Cowboys are nicknamed “America's Team.”","ja":"NFLのダラス・カウボーイズは「アメリカズ・チーム」と呼ばれる。"},{"k":"work","zh":"《勝利之光》描寫小鎮的高中美式足球狂熱，原作寫的是奧德薩的高中球隊。","en":"“Friday Night Lights” grew out of a book about a high-school football team in Odessa.","ja":"『フライデー・ナイト・ライツ』の原作は、オデッサの高校アメフト部を描いたノンフィクション。"},{"k":"festival","zh":"達拉斯州博覽會的看板人物是高約17公尺的牛仔巨像，2012年燒毀後重建。","en":"The state fair in Dallas is fronted by a 55-ft cowboy figure, rebuilt after a 2012 fire.","ja":"ダラスの州フェアの名物は高さ約17mのカウボーイ像で、2012年に焼失し再建された。"},{"k":"origin","zh":"州名源自卡多族語「朋友」，西班牙人拿來稱呼當地的部族。","en":"The name comes from a Caddo word for “friends,” which the Spanish applied to local peoples.","ja":"州名はカド語の「友」に由来し、スペイン人が地元の部族を指して使った。"},{"k":"symbol","zh":"州定小型哺乳動物是九帶犰狳，牠每胎都生下基因相同的四胞胎。","en":"The state small mammal is the nine-banded armadillo, which gives birth to identical quadruplets.","ja":"州の小型哺乳類はココノオビアルマジロで、毎回遺伝的に同一の四つ子を産む。"},{"k":"symbol","zh":"州菜是辣肉醬，州定零食是玉米片配莎莎醬。","en":"The state dish is chili, and the state snack is tortilla chips and salsa.","ja":"州の料理はチリ、州のスナックはトルティーヤチップスとサルサ。"}],
"US-UT":[{"k":"people","zh":"電子電視的發明人菲洛·法恩斯沃斯，1906年生於○○的比弗附近。","en":"Philo Farnsworth, inventor of electronic television, was born near Beaver, ○○, in 1906.","ja":"電子式テレビを発明したファイロ・ファーンズワースは、1906年に○○のビーバー近郊で生まれた。"},{"k":"people","zh":"西部大盜布屈·卡西迪1866年生於○○的比弗。","en":"Outlaw Butch Cassidy was born in Beaver, ○○, in 1866.","ja":"西部の強盗ブッチ・キャシディは1866年、○○のビーバーで生まれた。"},{"k":"sport","zh":"NBA○○爵士隊原本在爵士樂發源地紐奧良，1979年搬來後沿用了隊名。","en":"The NBA's ○○ Jazz began in New Orleans, the birthplace of jazz, and kept the name after moving in 1979.","ja":"NBAの○○・ジャズはジャズ発祥の地ニューオーリンズで生まれ、1979年の移転後も名前を変えなかった。"},{"k":"work","zh":"電影《127小時》改編自登山客受困峽谷、自斷手臂脫困的真實事件，地點在○○。","en":"“127 Hours” retells a climber's real ordeal of cutting off his own arm to escape a canyon in ○○.","ja":"映画『127時間』は、○○の峡谷で岩に挟まれ、自ら腕を切って脱出した登山者の実話。"},{"k":"festival","zh":"每年7月24日是「拓荒者日」州定假日，紀念1847年摩門教拓荒者抵達。","en":"July 24 is Pioneer Day, a state holiday marking the arrival of Mormon pioneers in 1847.","ja":"7月24日は州の祝日「パイオニア・デー」。1847年のモルモン開拓者の到着を記念する。"},{"k":"symbol","zh":"州鳥是加州海鷗，傳說1848年海鷗吃掉成群螽斯，救了移民的農作物。","en":"The state bird is the California gull, said to have saved settlers' crops in 1848 by eating swarms of crickets.","ja":"州の鳥はカリフォルニアカモメ。1848年、作物を襲う虫の大群を食べて開拓者を救ったと伝わる。"},{"k":"origin","zh":"州名來自當地原住民尤特族，常被解釋為「山上的人」。","en":"The name comes from the Ute people and is often said to mean “people of the mountains.”","ja":"州名は先住民ユート族に由来し、「山の民」の意味だとよく言われる。"},{"k":"life","zh":"○○首府曾是全美人均吃最多Jell-O果凍的城市，州議會還認證它是「最愛零食」。","en":"○○'s capital once led the US in Jell-O eaten per person, and lawmakers named it a favorite state snack.","ja":"○○の州都はかつてジェローの1人当たり消費量が全米一で、州議会は「州の好物スナック」に認定した。"}],
"US-VA":[{"k":"people","zh":"爵士天后艾拉·費茲傑羅出生於紐波特紐斯。","en":"Jazz queen Ella Fitzgerald was born in Newport News.","ja":"ジャズの女王エラ・フィッツジェラルドはニューポートニューズ生まれ。"},{"k":"people","zh":"女星珊卓·布拉克出生於阿靈頓。","en":"Actress Sandra Bullock was born in Arlington.","ja":"女優サンドラ・ブロックはアーリントン生まれ。"},{"k":"festival","zh":"每年七月的小馬泳渡活動，兩百多匹野生小馬會游過海峽到欽科蒂格島。","en":"Each July, over 200 wild ponies swim across the Assateague Channel to Chincoteague in the annual Pony Penning.","ja":"毎年7月のポニー・ペニングでは、200頭以上の野生ポニーが海峡を泳いでチンコティーグ島へ渡る。"},{"k":"origin","zh":"州名一般認為是紀念終身未婚、被稱為「童貞女王」的英國女王伊莉莎白一世。","en":"The name is thought to honor England's unmarried Elizabeth I, the \"Virgin Queen.\"","ja":"州名は生涯独身で「処女王」と呼ばれた英女王エリザベス1世にちなむとされる。"},{"k":"symbol","zh":"州犬是美國獵狐犬，連喬治·華盛頓都親自養過、育種過。","en":"The state dog is the American Foxhound, a breed George Washington himself raised and bred.","ja":"州の犬はアメリカン・フォックスハウンド。ジョージ・ワシントン自身も飼育・繁殖していた。"},{"k":"work","zh":"電影《衝鋒陷陣》講述亞歷山卓一所高中美式足球隊打破種族隔閡的真實故事。","en":"The film Remember the Titans tells the true story of an Alexandria high school football team uniting across racial lines.","ja":"映画『タイタンズを忘れない』は、人種の壁を越えたアレクサンドリアの高校アメフト部の実話。"},{"k":"sport","zh":"NFL華盛頓指揮官隊的訓練基地其實設在○○的勞登郡。","en":"The NFL's Washington Commanders actually train in Loudoun County, ○○.","ja":"NFLワシントン・コマンダースの練習施設は、実は○○のラウドン郡にある。"},{"k":"record","zh":"州議會從1619年開始召開，是北美洲歷史最悠久的立法機構。","en":"Its legislature first met in 1619, making it the oldest legislative body in North America.","ja":"州議会は1619年に初めて開かれた、北米で最も古い立法機関。"}],
"US-VT":[{"k":"people","zh":"1923 年柯立芝在○○老家的客廳接任總統，由父親為他監誓。","en":"In 1923 Coolidge took the presidential oath in the parlor of his ○○ family home, sworn in by his father.","ja":"1923年、クーリッジは○○の実家の居間で、父の立ち会いのもと大統領就任の宣誓をした。"},{"k":"people","zh":"發明鋼犁、創立強鹿公司的約翰·迪爾，出生在○○的拉特蘭。","en":"John Deere, who made the steel plow and founded Deere & Company, was born in Rutland, ○○.","ja":"鋼鉄のすきを作りディア・アンド・カンパニーを創業したジョン・ディアは○○のラトランド生まれ。"},{"k":"work","zh":"電影《銀色聖誕》裡的旅館，位在○○的虛構小鎮松樹鎮。","en":"The inn in the film White Christmas is in Pine Tree, a fictional ○○ town.","ja":"映画『ホワイト・クリスマス』の宿は、○○の架空の町パイン・ツリーにある。"},{"k":"life","zh":"《真善美》的原型特拉普家族逃離奧地利後，定居在○○的斯托。","en":"The von Trapp family, who inspired The Sound of Music, settled in Stowe, ○○, after fleeing Austria.","ja":"『サウンド・オブ・ミュージック』のトラップ一家は、オーストリアを逃れて○○のストウに定住した。"},{"k":"sport","zh":"滑雪板品牌 Burton 1977 年在○○創立，推動了單板滑雪的普及。","en":"Burton Snowboards was founded in ○○ in 1977 and helped popularize snowboarding.","ja":"スノーボードブランドのバートンは1977年に○○で創業し、スノボ普及の立役者に。"},{"k":"festival","zh":"聖奧爾本斯每年 4 月最後一個週末，都會舉辦三天的楓糖節。","en":"St. Albans holds a three-day maple festival every year on the last weekend of April.","ja":"セント・オールバンズでは毎年4月最後の週末、3日間のメープル祭りが開かれる。"},{"k":"origin","zh":"州名來自法語的「綠色的山」，指縱貫全州的山脈。","en":"The name is French for green mountain, after the range running through the state.","ja":"州名はフランス語で「緑の山」。州を縦断する山脈にちなむ。"},{"k":"symbol","zh":"數字 14 在州史裡一再出現：當了 14 年共和國、有 14 個郡、是第 14 州。","en":"The number 14 keeps turning up in the state's history: 14 years as a republic, 14 counties, and the 14th state.","ja":"数字の14が州の歴史に何度も登場する。共和国だった14年、14の郡、14番目の州。"}],
"US-WA":[{"k":"people","zh":"傳奇吉他手吉米·罕醉克斯1942年生於西雅圖。","en":"Guitar legend Jimi Hendrix was born in Seattle in 1942.","ja":"伝説のギタリスト、ジミ・ヘンドリックスは1942年にシアトルで生まれた。"},{"k":"people","zh":"比爾·蓋茲生於西雅圖，微軟總部也設在附近的雷德蒙德。","en":"Bill Gates was born in Seattle, and Microsoft is headquartered in nearby Redmond.","ja":"ビル・ゲイツはシアトル生まれで、マイクロソフトの本社も近くのレドモンドにある。"},{"k":"sport","zh":"鈴木一朗2001年加盟水手隊，當年同時拿下新人王和MVP。","en":"Ichiro Suzuki joined the Mariners in 2001 and won both Rookie of the Year and MVP that season.","ja":"イチローは2001年にマリナーズ入りし、その年に新人王とMVPを同時に受賞した。"},{"k":"work","zh":"小說《暮光之城》的故事發生在奧林匹克半島上多雨的小鎮福克斯。","en":"“Twilight” is set in Forks, a rainy small town on the Olympic Peninsula.","ja":"小説『トワイライト』の舞台は、オリンピック半島の雨の多い小さな町フォークス。"},{"k":"festival","zh":"斯卡吉特谷鬱金香節自1984年起每年4月舉行，花田綿延數百英畝。","en":"Since 1984 the Skagit Valley Tulip Festival has filled hundreds of acres with blooms every April.","ja":"1984年から毎年4月に開かれるスカジット・バレー・チューリップ祭りでは、数百エーカーの花畑が咲く。"},{"k":"origin","zh":"原本要叫「哥倫比亞」，為了避免和首都特區混淆，才改用首任總統的名字。","en":"It was nearly named Columbia, but Congress chose the first president's name to avoid confusion with D.C.","ja":"当初は「コロンビア」となる予定だったが、首都D.C.と紛らわしいため初代大統領の名前になった。"},{"k":"record","zh":"大古力水壩裝置容量6,809百萬瓦，是全美最大的發電廠。","en":"Grand Coulee Dam, with a nameplate capacity of 6,809 MW, is the largest power station in the US.","ja":"グランドクーリー・ダムは設備容量6809メガワットで、全米最大の発電所。"}],
"US-WI":[{"k":"people","zh":"脫逃魔術大師胡迪尼生於布達佩斯，童年在阿普爾頓度過。","en":"Escape artist Harry Houdini, born in Budapest, spent his childhood in Appleton.","ja":"脱出王フーディーニはブダペスト生まれで、幼少期をアップルトンで過ごした。"},{"k":"people","zh":"《大國民》的導演兼主演奧森·威爾斯出生在基諾沙。","en":"Orson Welles, director and star of “Citizen Kane,” was born in Kenosha.","ja":"『市民ケーン』の監督・主演オーソン・ウェルズはケノーシャ生まれ。"},{"k":"sport","zh":"綠灣包裝工是全美唯一由社區持有的非營利職業大聯盟球隊，球迷就是股東。","en":"The Green Bay Packers are the only nonprofit, community-owned major-league pro team in the U.S.—fans are the shareholders.","ja":"グリーンベイ・パッカーズは米国で唯一の地域住民所有の非営利プロチームで、ファンが株主。"},{"k":"work","zh":"影集《歡樂時光》以密爾瓦基為舞台，《70年代秀》則發生在州內的虛構小鎮。","en":"“Happy Days” was set in Milwaukee, and “That '70s Show” in a fictional town in the state.","ja":"ドラマ『ハッピーデイズ』の舞台はミルウォーキー、『ザット'70sショー』は州内の架空の町。"},{"k":"festival","zh":"密爾瓦基的夏日音樂節1999年獲金氏紀錄認證為「世界最大音樂節」。","en":"Milwaukee's Summerfest was certified by Guinness in 1999 as the world's largest music festival.","ja":"ミルウォーキーの「サマーフェスト」は1999年にギネスで世界最大の音楽祭と認定された。"},{"k":"origin","zh":"州名源自原住民對同名河流的稱呼，法國人最早記成「Meskousing」。","en":"The name comes from a Native name for the river of the same name, first written by the French as “Meskousing.”","ja":"州名は同名の川の先住民語名に由来し、フランス人が最初「メスクーシング」と記した。"},{"k":"symbol","zh":"州定舞蹈是波卡舞，州定糕點是丹麥酥，2017年連起司都成了州定乳製品。","en":"The state dance is the polka, the state pastry is the kringle, and since 2017 cheese is the state dairy product.","ja":"州のダンスはポルカ、州の菓子はクリングル。2017年にはチーズが州の乳製品になった。"},{"k":"life","zh":"許多餐廳週五晚上都有「炸魚之夜」，源自天主教徒週五不吃肉的傳統。","en":"Many restaurants hold a Friday night fish fry, a custom rooted in the Catholic tradition of skipping meat on Fridays.","ja":"多くの店が金曜夜に「フィッシュフライ」を出す。金曜に肉を控えるカトリックの習慣の名残。"}],
"US-WV":[{"k":"people","zh":"首位突破音障的飛行員查克·葉格出生於○○的小鎮。","en":"Chuck Yeager, the first pilot to break the sound barrier, was born in a small town in ○○.","ja":"初めて音速の壁を破ったパイロット、チャック・イェーガーは○○の小さな町の生まれ。"},{"k":"people","zh":"電影《關鍵少數》中的NASA數學家凱瑟琳·強森出生於白硫磺泉。","en":"NASA mathematician Katherine Johnson, featured in Hidden Figures, was born in White Sulphur Springs.","ja":"映画『ドリーム』で描かれたNASAの数学者キャサリン・ジョンソンはホワイトサルファースプリングス生まれ。"},{"k":"people","zh":"以中國農村為題材的小說《大地》作者賽珍珠，出生於○○的希爾斯伯勒。","en":"Pearl S. Buck, author of The Good Earth set in rural China, was born in Hillsboro, ○○.","ja":"中国の農村を描いた『大地』の作者パール・バックは○○のヒルズボロ生まれ。"},{"k":"work","zh":"電玩《異塵餘生76》的舞台就是核戰後的○○。","en":"The video game Fallout 76 is set in a post-nuclear-war ○○.","ja":"ゲーム『Fallout 76』の舞台は核戦争後の○○。"},{"k":"work","zh":"電影《十月的天空》改編自煤礦小鎮科爾伍德少年們自製火箭的真實故事。","en":"The film October Sky is based on the true story of boys building rockets in the coal town of Coalwood.","ja":"映画『遠い空の向こうに』は、炭鉱町コールウッドの少年たちがロケットを作った実話。"},{"k":"festival","zh":"「大橋日」在每年十月第三個星期六，數百人可以合法從新河峽谷大橋跳傘。","en":"On Bridge Day, the third Saturday of October, hundreds are allowed to BASE jump off the New River Gorge Bridge.","ja":"10月第3土曜の「ブリッジ・デー」には、数百人がニューリバー・ゴージ橋からのベースジャンプを許される。"},{"k":"sport","zh":"州立大學美式足球主場自1972年起，每場賽前都會播放〈Country Roads〉。","en":"Since 1972, \"Country Roads\" has been played before every home football game of the state university.","ja":"州立大学のアメフトのホーム戦では、1972年から毎試合前に「カントリー・ロード」が流れる。"},{"k":"symbol","zh":"2005年發行的州紀念25分硬幣，背面圖案就是新河峽谷大橋。","en":"The state's 2005 quarter shows the New River Gorge Bridge on its reverse.","ja":"2005年発行の州記念25セント硬貨の裏面には、ニューリバー・ゴージ橋が描かれている。"}],
"US-WY":[{"k":"people","zh":"抽象畫家傑克遜·波洛克1912年生於○○的科迪。","en":"Abstract painter Jackson Pollock was born in Cody, ○○, in 1912.","ja":"抽象画家ジャクソン・ポロックは1912年、○○のコーディで生まれた。"},{"k":"people","zh":"西部秀明星水牛比爾在1896年創建了○○的小鎮科迪。","en":"Wild West showman Buffalo Bill founded the town of Cody, ○○, in 1896.","ja":"西部劇ショーのスター、バッファロー・ビルは1896年に○○の町コーディを創設した。"},{"k":"work","zh":"史匹柏電影《第三類接觸》的高潮場景就在魔鬼塔。","en":"The climax of Spielberg's “Close Encounters of the Third Kind” takes place at Devils Tower.","ja":"スピルバーグ監督『未知との遭遇』のクライマックスはデビルスタワーが舞台。"},{"k":"work","zh":"李安電影《斷背山》裡，兩位牛仔1963年在○○的山上牧羊時相識。","en":"In Ang Lee's “Brokeback Mountain,” two cowboys meet while herding sheep on a ○○ mountain in 1963.","ja":"アン・リー監督『ブロークバック・マウンテン』で、2人のカウボーイは1963年に○○の山で羊番として出会う。"},{"k":"festival","zh":"自1897年起每年7月舉行的「邊疆節」，自稱世界最大的戶外牛仔競技會。","en":"Held every July since 1897, Frontier Days bills itself as the world's largest outdoor rodeo.","ja":"1897年から毎年7月に開かれる「フロンティア・デイズ」は、世界最大の屋外ロデオを名乗る。"},{"k":"sport","zh":"全美大學牛仔競技總決賽自1999年起在○○的卡斯珀舉行。","en":"The College National Finals Rodeo has been held in Casper, ○○, since 1999.","ja":"全米大学ロデオ決勝大会は1999年から○○のキャスパーで開かれている。"},{"k":"origin","zh":"州名借自賓州的一座河谷，源自原住民語「大河邊的平地」。","en":"The name was borrowed from a valley in Pennsylvania, from a Native word meaning “at the big river flat.”","ja":"州名はペンシルベニア州の谷の名前を借りたもの。もとは先住民の言葉で「大きな川辺の平地」。"},{"k":"symbol","zh":"○○的州旗中央畫著一頭白色的美洲野牛。","en":"○○'s state flag shows a white bison at its center.","ja":"○○の州旗の中央には白いバイソンが描かれている。"}]};
